/* Altus Aerials API — Cloudflare Worker
 *
 * Serves client galleries (HTML with per-gallery link previews), photos/zips from R2,
 * view/download pings, no-login booking requests, and Hadi's studio API.
 *
 * Bindings (Worker → Settings → Bindings):
 *   MEDIA  R2 bucket   altus-galleries
 *   DB     D1 database altus-db
 * Secrets / variables (Worker → Settings → Variables and Secrets):
 *   STUDIO_KEY           secret   passphrase for the studio pages
 *   PUBLIC_ORIGIN        text     https://altusaerials.com  (leave empty while testing on workers.dev)
 *   FIREBASE_API_KEY     text     Flightpath's Firebase Web API key (Project settings → General)
 *   FP_EMAIL             text     sign-in email of the Flightpath account the gallery system uses
 *   FP_PASSWORD          secret   that account's password
 *   (FIREBASE_SA         secret   alternative: service-account JSON, if your Google org allows keys)
 *   AUTO_SEND            text     "false" (flip to "true" once Twilio is registered)
 *   TWILIO_SID / TWILIO_TOKEN / TWILIO_FROM   (later)
 *
 * The build step (tools/build_worker.py) inlines the front-end files as ASSETS below.
 */

const ASSETS = {"/assets/gallery/template.html": {"type": "text/html; charset=utf-8", "body": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"theme-color\" content=\"#071a33\">\n<!--OG-->\n<link rel=\"icon\" href=\"__API__/assets/images/favicon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Inter:wght@400;500;600;700&display=swap\">\n<link rel=\"stylesheet\" href=\"__API__/assets/gallery/gallery.css?v=c7173b0be9\">\n</head>\n<body>\n<div id=\"app\"></div>\n<!--DATA-->\n<script src=\"__API__/assets/gallery/gallery.js?v=c7173b0be9\"></script>\n</body>\n</html>\n"}, "/assets/gallery/gallery.css": {"type": "text/css; charset=utf-8", "body": "/* Altus Aerials \u2014 client gallery\n[hidden] { display: none !important; }\n   Layout: full-bleed twilight cover \u2192 action row \u2192 sticky section chips \u2192\n   photo grids (EXT / INT) \u2192 floor plans \u2192 3D tour + explainer \u2192 rebook \u2192 footer.\n   Tokens mirror assets/css/style.css on the main site. */\n:root {\n  --navy: #0b2545;\n  --navy-deep: #071a33;\n  --blue: #4c8dff;\n  --blue-light: #8ec5ff;\n  --ink: #101828;\n  --muted: #5b6474;\n  --paper: #ffffff;\n  --paper-soft: #f6f8fb;\n  --line: #e4e8ef;\n  --chip: #e9eef7;\n  --warn-bg: #fff6db;\n  --warn-ink: #7a5600;\n  --warn-line: #f0d48a;\n  --shadow: 0 10px 30px rgba(11, 37, 69, .14);\n  --radius: 14px;\n  --max: 1180px;\n  --serif: \"Fraunces\", Georgia, \"Times New Roman\", serif;\n  --sans: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --safe-b: env(safe-area-inset-bottom, 0px);\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --ink: #e8edf5; --muted: #9aa6b8; --paper: #0d1a2c; --paper-soft: #081322;\n    --line: #1f3048; --chip: #15263d; --navy: #dfe9ff; --warn-bg: #2d2410;\n    --warn-ink: #f3d27a; --warn-line: #5c4a1c; --shadow: 0 10px 30px rgba(0,0,0,.4);\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --ink: #e8edf5; --muted: #9aa6b8; --paper: #0d1a2c; --paper-soft: #081322;\n  --line: #1f3048; --chip: #15263d; --navy: #dfe9ff; --warn-bg: #2d2410;\n  --warn-ink: #f3d27a; --warn-line: #5c4a1c; --shadow: 0 10px 30px rgba(0,0,0,.4);\n  color-scheme: dark;\n}\n\n* { box-sizing: border-box; }\nhtml { -webkit-text-size-adjust: 100%; scroll-padding-top: 64px; }\nbody {\n  margin: 0; background: var(--paper-soft); color: var(--ink);\n  font: 16px/1.55 var(--sans); -webkit-font-smoothing: antialiased;\n}\nimg { max-width: 100%; display: block; }\nbutton { font: inherit; color: inherit; }\na { color: inherit; }\n:focus-visible { outline: 3px solid var(--blue); outline-offset: 2px; }\n.wrap { max-width: var(--max); margin: 0 auto; padding-inline: 16px; }\n@media (min-width: 720px) { .wrap { padding-inline: 28px; } }\n\n/* ---------- Cover ---------- */\n.cover {\n  position: relative; min-height: min(78svh, 720px); display: flex; flex-direction: column;\n  justify-content: space-between; color: #fff; background: #071a33; overflow: hidden; isolation: isolate;\n}\n.cover-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: -2; }\n.cover::after {\n  content: \"\"; position: absolute; inset: 0; z-index: -1;\n  background: linear-gradient(180deg, rgba(7,26,51,.55) 0%, rgba(7,26,51,0) 28%, rgba(7,26,51,0) 45%, rgba(7,26,51,.88) 100%);\n}\n.topbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-block: 16px; }\n.icon-btn {\n  display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 14px; border-radius: 999px;\n  border: 1px solid rgba(255,255,255,.35); background: rgba(7,26,51,.35); backdrop-filter: blur(8px);\n  -webkit-backdrop-filter: blur(8px); color: #fff; cursor: pointer; font-size: 14px; font-weight: 600;\n}\n.icon-btn svg { width: 18px; height: 18px; }\n.cover-text { padding-block: 0 28px; }\n.eyebrow {\n  display: inline-flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 0 0 10px;\n  font: 600 12px/1.3 var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--blue-light);\n}\n.pkg-badge { padding: 5px 10px; border-radius: 999px; background: rgba(76,141,255,.22); border: 1px solid rgba(142,197,255,.5); color: #fff; }\n.cover h1 {\n  margin: 0; font: 500 clamp(34px, 9vw, 64px)/1.05 var(--serif); letter-spacing: -.01em; text-wrap: balance;\n}\n.cover .sub { margin: 10px 0 0; font-size: 15px; color: rgba(255,255,255,.82); }\n\n/* ---------- Actions ---------- */\n.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; padding-block: 18px 6px; }\n.btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 50px; padding: 12px 20px;\n  border-radius: 999px; border: 1px solid transparent; cursor: pointer; text-decoration: none;\n  font: 600 14px/1.1 var(--sans); letter-spacing: .03em; text-transform: uppercase;\n  transition: transform .2s ease, box-shadow .2s ease, background .2s ease;\n}\n.btn svg { width: 18px; height: 18px; flex: none; }\n.btn-primary { background: #0b2545; color: #fff; box-shadow: 0 8px 24px rgba(11,37,69,.25); grid-column: 1 / -1; }\n.btn-primary:hover { transform: translateY(-2px); }\n.btn-blue { background: var(--blue); color: #fff; }\n.btn-outline { background: var(--paper); border-color: var(--line); color: var(--ink); }\n.btn[disabled] { opacity: .7; cursor: progress; }\n.actions .meta { grid-column: 1 / -1; margin: 2px 0 0; color: var(--muted); font-size: 13px; text-align: center; }\n@media (min-width: 720px) {\n  .actions { grid-template-columns: auto auto auto 1fr; align-items: center; }\n  .btn-primary { grid-column: auto; }\n  .actions .meta { grid-column: auto; text-align: right; }\n}\n\n/* ---------- Section nav ---------- */\n.chips {\n  position: sticky; top: env(safe-area-inset-top, 0px); z-index: 20; background: color-mix(in srgb, var(--paper-soft) 92%, transparent);\n  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border-bottom: 1px solid var(--line);\n}\n.chips .wrap { display: flex; gap: 8px; overflow-x: auto; padding-block: 10px; scrollbar-width: none; }\n.chips .wrap::-webkit-scrollbar { display: none; }\n.chip {\n  flex: none; display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 999px;\n  background: var(--chip); color: var(--ink); text-decoration: none; font-size: 14px; font-weight: 600; white-space: nowrap;\n}\n.chip small { font-weight: 500; color: var(--muted); font-variant-numeric: tabular-nums; }\n.chip.active { background: #0b2545; color: #fff; }\n.chip.active small { color: var(--blue-light); }\n\n/* ---------- Sections ---------- */\nsection.block { padding-block: 34px 8px; }\n.block-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 14px; }\n.block-head h2 { margin: 0; font: 500 clamp(26px, 6vw, 34px)/1.15 var(--serif); color: var(--navy); text-wrap: balance; }\n.block-head p { margin: 0; color: var(--muted); font-size: 14px; font-variant-numeric: tabular-nums; }\n.lede { margin: -6px 0 16px; color: var(--muted); max-width: 62ch; }\n\n.grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }\n@media (min-width: 720px) { .grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; } }\n@media (min-width: 1080px) { .grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }\n.tile {\n  position: relative; padding: 0; border: 0; background: var(--chip); border-radius: 10px; overflow: hidden;\n  aspect-ratio: 4 / 3; cursor: zoom-in;\n}\n.tile img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }\n@media (hover: hover) { .tile:hover img { transform: scale(1.04); } }\n.tile .tag {\n  position: absolute; left: 6px; top: 6px; padding: 3px 7px; border-radius: 999px; background: rgba(7,26,51,.72);\n  color: #fff; font-size: 11px; font-weight: 600; letter-spacing: .04em;\n}\n.tile.feature { grid-column: 1 / -1; aspect-ratio: 16 / 9; }\n@media (min-width: 720px) { .tile { border-radius: var(--radius); } }\n\n/* ---------- Placeholder notes (for Hadi) ---------- */\n.todo {\n  display: flex; gap: 10px; align-items: flex-start; margin: 0 0 14px; padding: 12px 14px; border-radius: 10px;\n  background: var(--warn-bg); color: var(--warn-ink); border: 1px dashed var(--warn-line); font-size: 13.5px;\n}\n.todo b { white-space: nowrap; }\n\n/* ---------- Floor plans ---------- */\n.plans { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; }\n@media (min-width: 720px) { .plans { grid-template-columns: repeat(2, minmax(0, 1fr)); } }\n.plan { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }\n.plan button.view { display: block; width: 100%; padding: 0; border: 0; background: #fff; cursor: zoom-in; }\n.plan img { width: 100%; aspect-ratio: 4 / 3; object-fit: contain; }\n.plan-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 14px; border-top: 1px solid var(--line); }\n.plan-foot strong { font-size: 15px; }\n.plan-foot small { display: block; color: var(--muted); font-size: 12.5px; }\n.mini {\n  display: inline-flex; align-items: center; gap: 6px; padding: 9px 14px; border-radius: 999px; border: 1px solid var(--line);\n  background: var(--paper-soft); cursor: pointer; font-size: 13px; font-weight: 600; white-space: nowrap; text-decoration: none;\n}\n.mini svg { width: 16px; height: 16px; }\n\n/* ---------- 3D tour ---------- */\n.tour { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }\n.tour-stage {\n  position: relative; aspect-ratio: 16 / 10; background: #071a33; color: #fff; display: grid; place-items: center; text-align: center;\n  isolation: isolate;\n}\n.tour-stage img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .45; z-index: -1; }\n.tour-stage iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }\n.tour-cta { display: grid; gap: 12px; justify-items: center; padding: 20px; }\n.tour-cta .ring {\n  width: 74px; height: 74px; border-radius: 50%; display: grid; place-items: center; background: rgba(255,255,255,.14);\n  border: 1px solid rgba(255,255,255,.45); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);\n}\n.tour-cta .ring svg { width: 34px; height: 34px; }\n.tour-cta p { margin: 0; font-size: 14px; color: rgba(255,255,255,.85); }\n.tour-link { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; padding: 12px 14px; border-top: 1px solid var(--line); }\n.tour-link code {\n  flex: 1 1 200px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 9px 12px;\n  border-radius: 8px; background: var(--paper-soft); font: 13px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--muted);\n}\n.explain { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; margin-top: 14px; }\n@media (min-width: 900px) { .explain { grid-template-columns: repeat(3, minmax(0, 1fr)); } }\n.explain article { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; }\n.explain h3 { margin: 0 0 8px; font: 500 20px/1.2 var(--serif); color: var(--navy); }\n.explain p, .explain li { margin: 0; color: var(--ink); font-size: 15px; }\n.explain ol, .explain ul { margin: 0; padding-left: 20px; display: grid; gap: 6px; }\n.explain .note { margin-top: 10px; color: var(--muted); font-size: 13.5px; }\n\n/* ---------- Rebook ---------- */\n.rebook { margin-top: 40px; background: #0b2545; color: #fff; }\n.rebook .wrap { padding-block: 40px; display: grid; gap: 18px; }\n.rebook h2 { margin: 0; font: 500 clamp(26px, 4vw, 38px)/1.15 var(--serif); text-wrap: balance; }\n.rebook p { margin: 0; color: rgba(255,255,255,.78); max-width: 56ch; }\n.pkgs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }\n@media (min-width: 900px) { .pkgs { grid-template-columns: repeat(4, minmax(0, 1fr)); } }\n.pkg { padding: 14px; border-radius: 12px; border: 1px solid rgba(142,197,255,.25); background: rgba(255,255,255,.04); }\n.pkg b { display: block; font-size: 15px; }\n.pkg span { display: block; margin-top: 2px; font: 500 26px/1.2 var(--serif); color: var(--blue-light); font-variant-numeric: tabular-nums; }\n.pkg small { display: block; margin-top: 4px; font-size: 12.5px; color: rgba(255,255,255,.7); line-height: 1.4; }\n.pkg.current { border-color: var(--blue); background: rgba(76,141,255,.14); }\n.rebook .btn { justify-self: start; }\n.btn-light { background: #fff; color: #0b2545; }\n\nfooter.foot { background: #071a33; color: rgba(255,255,255,.7); font-size: 13px; }\nfooter.foot .wrap { padding-block: 44px calc(96px + var(--safe-b)); display: grid; gap: 22px; }\nfooter.foot a { color: rgba(255,255,255,.7); text-decoration: none; }\nfooter.foot a:hover { color: #fff; }\n.foot-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px; padding-bottom: 22px; border-bottom: 1px solid rgba(255,255,255,.1); }\n.foot-top nav { display: flex; flex-wrap: wrap; gap: 20px; }\n.foot-top nav a { text-transform: uppercase; letter-spacing: .04em; }\n.foot-bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 10px; color: rgba(255,255,255,.45); }\n@media (min-width: 720px) { footer.foot .wrap { padding-bottom: 30px; } }\n/* Brand lock-up matches the site header: logo mark + Fraunces wordmark */\n.brand { display: inline-flex; align-items: center; gap: 10px; color: #fff; text-decoration: none; }\n.brand-mark { height: 32px; width: auto; }\n.brand-text { font: 400 20px/1 var(--serif); letter-spacing: .02em; color: #fff; }\n@media (max-width: 360px) { .brand-text { display: none; } }\n\n/* ---------- Sticky mobile dock ---------- */\n.dock {\n  position: fixed; left: 0; right: 0; bottom: 0; z-index: 30; display: grid; grid-template-columns: 1fr auto; gap: 8px;\n  padding: 10px 12px calc(10px + var(--safe-b)); background: color-mix(in srgb, var(--paper) 94%, transparent);\n  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border-top: 1px solid var(--line);\n  transform: translateY(110%); transition: transform .25s ease;\n}\n.dock.show { transform: none; }\n.dock .btn { min-height: 46px; }\n.dock .btn-primary { grid-column: auto; }\n@media (min-width: 720px) { .dock { display: none; } }\n\n/* ---------- Lightbox ---------- */\n.lb { position: fixed; inset: 0; z-index: 100; background: #050d18; color: #fff; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; }\n.lb[hidden] { display: none; }\n.lb-top, .lb-bottom { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 14px; }\n.lb-top { padding-top: calc(12px + env(safe-area-inset-top, 0px)); }\n.lb-bottom { padding-bottom: calc(14px + var(--safe-b)); }\n.lb-count { font-size: 14px; font-variant-numeric: tabular-nums; color: rgba(255,255,255,.75); }\n.lb-stage { position: relative; overflow: hidden; touch-action: pan-y; min-height: 0; }\n.lb-stage img { position: absolute; inset: 0; width: 100%; height: 100%; max-width: none; object-fit: contain; user-select: none; -webkit-user-drag: none; transition: transform .2s ease, opacity .2s ease; }\n.lb-nav {\n  position: absolute; top: 50%; transform: translateY(-50%); width: 48px; height: 48px; border-radius: 50%; border: 0;\n  background: rgba(255,255,255,.12); color: #fff; cursor: pointer; display: none; place-items: center;\n}\n.lb-nav svg { width: 22px; height: 22px; }\n.lb-prev { left: 14px; } .lb-next { right: 14px; }\n@media (hover: hover) { .lb-nav { display: grid; } }\n.lb .icon-btn { background: rgba(255,255,255,.08); }\n.lb-name { font-size: 13px; color: rgba(255,255,255,.65); }\n\n/* ---------- Toast + password gate ---------- */\n.toast {\n  position: fixed; left: 50%; bottom: calc(84px + var(--safe-b)); transform: translate(-50%, 20px); z-index: 120; opacity: 0;\n  padding: 11px 18px; border-radius: 999px; background: #0b2545; color: #fff; font-size: 14px; font-weight: 600;\n  box-shadow: var(--shadow); transition: opacity .2s ease, transform .2s ease; pointer-events: none; max-width: calc(100% - 32px);\n}\n.toast.show { opacity: 1; transform: translate(-50%, 0); }\n.gate { position: fixed; inset: 0; z-index: 200; display: grid; place-items: center; padding: 16px; background: #071a33; color: #fff; isolation: isolate; }\n.gate img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .28; filter: blur(14px); z-index: -1; transform: scale(1.1); }\n.gate form { width: min(380px, 100%); display: grid; gap: 12px; text-align: center; }\n.gate h2 { margin: 0; font: 500 30px/1.15 var(--serif); }\n.gate p { margin: 0; color: rgba(255,255,255,.78); font-size: 15px; }\n.gate input {\n  height: 52px; padding: 0 16px; border-radius: 12px; border: 1px solid rgba(255,255,255,.3); background: rgba(255,255,255,.1);\n  color: #fff; font: 16px var(--sans); text-align: center;\n}\n.gate .err { color: #ffb4b4; font-size: 14px; min-height: 1.2em; }\n\n.proto-banner {\n  background: var(--warn-bg); color: var(--warn-ink); border-bottom: 1px solid var(--warn-line); font-size: 13px; text-align: center; padding: 8px 16px;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { transition: none !important; animation: none !important; scroll-behavior: auto !important; }\n}\n.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n.cover > .wrap { width: 100%; }\n.cover .city { margin: 8px 0 0; font: 500 clamp(17px, 4.6vw, 22px)/1.3 var(--sans); color: #fff; }\n.cover .city + .sub { margin-top: 4px; font-size: 14px; }\n"}, "/assets/gallery/gallery.js": {"type": "text/javascript; charset=utf-8", "body": "/* Altus Aerials \u2014 client gallery renderer.\n   Reads one JSON object (inline <script id=\"gallery-data\"> today; R2 JSON in phase 2)\n   and builds the whole page. No framework, no build step. */\n(function () {\n  \"use strict\";\n  var $ = function (s, r) { return (r || document).querySelector(s); };\n  var esc = function (s) { return String(s == null ? \"\" : s).replace(/[&<>\"']/g, function (c) { return { \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]; }); };\n  var D, base, ext, int, isSignature, coverPhoto;\n  var full = function (p) { return base + \"full/\" + p.id + \".jpg\"; };\n  var thumb = function (p) { return base + \"thumb/\" + p.id + \".jpg\"; };\n  var fileName = function (p) { return \"(\" + p.kind + \") Image \" + p.n + \".jpg\"; };\n  function setup(data) {\n    D = data;\n    base = D.imageBase.replace(/\\/?$/, \"/\");\n    ext = D.photos.filter(function (p) { return p.kind === \"EXT\"; });\n    int = D.photos.filter(function (p) { return p.kind === \"INT\"; });\n    isSignature = /signature|summit/i.test(D.package);\n    coverPhoto = D.photos.filter(function (p) { return p.id === D.cover; })[0] || ext[0] || D.photos[0];\n  }\n\n  var ICON = {\n    dl: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12m0 0-5-5m5 5 5-5M4 19h16\"/></svg>',\n    share: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 15V3m0 0L7.5 7.5M12 3l4.5 4.5M6 11H5a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-8a1 1 0 0 0-1-1h-1\"/></svg>',\n    cal: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M3 10h18M8 3v4M16 3v4\"/></svg>',\n    x: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6 6 18\"/></svg>',\n    l: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m15 5-7 7 7 7\"/></svg>',\n    r: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m9 5 7 7-7 7\"/></svg>',\n    cube: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 2.5 20.5 7v10L12 21.5 3.5 17V7z\"/><path d=\"M3.5 7 12 11.5 20.5 7M12 11.5v10\"/></svg>',\n    copy: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"9\" y=\"9\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M5 15V5a2 2 0 0 1 2-2h10\"/></svg>',\n    ext: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5\"/></svg>'\n  };\n\n  /* ---------- tracking ping (no-op until D.pingUrl is set) ---------- */\n  var visitor = (function () { try { var v = sessionStorage.getItem(\"altus_v\"); if (!v) { v = Math.random().toString(36).slice(2, 12); sessionStorage.setItem(\"altus_v\", v); } return v; } catch (e) { return \"\"; } })();\n  function ping(event, extra) {\n    try { if (localStorage.getItem(\"altus_owner\")) return; } catch (e) {}\n    var body = JSON.stringify(Object.assign({ g: D.slug, e: event, v: visitor }, extra || {}));\n    if (!D.pingUrl) { if (window.console) console.debug(\"[ping]\", body); return; }\n    try { navigator.sendBeacon ? navigator.sendBeacon(D.pingUrl, body) : fetch(D.pingUrl, { method: \"POST\", body: body, keepalive: true }); } catch (e) {}\n  }\n\n  var toastT;\n  function toast(msg) {\n    var t = $(\"#toast\"); t.textContent = msg; t.classList.add(\"show\");\n    clearTimeout(toastT); toastT = setTimeout(function () { t.classList.remove(\"show\"); }, 2400);\n  }\n\n  /* ---------- render ---------- */\n  function tiles(list, startIdx) {\n    return list.map(function (p, i) {\n      return '<button class=\"tile\" type=\"button\" data-i=\"' + (startIdx + i) + '\" aria-label=\"Open ' + esc(fileName(p)) + '\">' +\n        '<img src=\"' + thumb(p) + '\" alt=\"' + (p.kind === \"EXT\" ? \"Exterior\" : \"Interior\") + ' photo ' + p.n + '\" loading=\"lazy\" decoding=\"async\" width=\"' + p.tw + '\" height=\"' + p.th + '\"></button>';\n    }).join(\"\");\n  }\n\n  function render() {\n    document.title = D.address + \" | Altus Aerials\";\n    var dateTxt = new Date(D.shootDate + \"T12:00:00\").toLocaleDateString(\"en-US\", { month: \"long\", day: \"numeric\", year: \"numeric\" });\n    var chips = [\n      [\"exteriors\", \"Exteriors\", ext.length], [\"interiors\", \"Interiors\", int.length]\n    ];\n    if (isSignature) { chips.push([\"floor-plans\", \"Floor plans\", D.floorPlans.length]); chips.push([\"tour\", \"3D tour\", \"\"]); }\n    chips.push([\"book\", \"Book again\", \"\"]);\n\n    var html = \"\";\n    if (D.prototype) html += '<div class=\"proto-banner\">' + esc(D.banner || \"Prototype preview. Yellow notes mark items Hadi still needs to supply.\") + '</div>';\n    html +=\n      '<header class=\"cover\">' +\n        '<img class=\"cover-img\" src=\"' + full(coverPhoto) + '\" alt=\"Twilight exterior of ' + esc(D.address) + '\" fetchpriority=\"high\">' +\n        '<div class=\"wrap topbar\"><a class=\"brand\" href=\"https://altusaerials.com/\" aria-label=\"Altus Aerials home\"><img class=\"brand-mark\" src=\"' + esc(D.logo || \"/assets/images/logo-white.png\") + '\" alt=\"\" width=\"50\" height=\"32\"><span class=\"brand-text\">Altus Aerials</span></a>' +\n          '<button class=\"icon-btn\" type=\"button\" data-act=\"share\">' + ICON.share + 'Share</button></div>' +\n        '<div class=\"wrap cover-text\"><p class=\"eyebrow\"><span class=\"pkg-badge\">' + esc(D.package) + ' Package</span><span>Shot ' + dateTxt + '</span></p>' +\n          '<h1>' + esc(D.address) + '</h1>' +\n          (D.cityLine ? '<p class=\"city\">' + esc(D.cityLine) + '</p>' : '') + '<p class=\"sub\">' + D.photos.length + ' photos' + (isSignature ? ' \u00b7 floor plans \u00b7 3D tour' : '') + '</p></div>' +\n      '</header>' +\n      '<div class=\"wrap actions\" id=\"actions\">' +\n        '<button class=\"btn btn-primary\" type=\"button\" data-act=\"zip\">' + ICON.dl + '<span>Download all ' + D.photos.length + ' photos</span></button>' +\n        '<button class=\"btn btn-outline\" type=\"button\" data-act=\"share\">' + ICON.share + 'Share</button>' +\n        '<a class=\"btn btn-outline\" href=\"#book\">' + ICON.cal + 'Book</a>' +\n        '<p class=\"meta\">MLS-ready JPEGs, 1920px on the long edge. Tap any photo to view or save it.</p>' +\n      '</div>' +\n      '<nav class=\"chips\" aria-label=\"Gallery sections\"><div class=\"wrap\">' +\n        chips.map(function (c) { return '<a class=\"chip\" href=\"#' + c[0] + '\">' + c[1] + (c[2] !== \"\" ? \" <small>\" + c[2] + \"</small>\" : \"\") + \"</a>\"; }).join(\"\") +\n      '</div></nav><main>' +\n      '<section class=\"block wrap\" id=\"exteriors\"><div class=\"block-head\"><h2>Exteriors</h2><p>' + ext.length + ' photos</p></div>' +\n        '<div class=\"grid\">' + tiles(ext, 0) + '</div></section>' +\n      '<section class=\"block wrap\" id=\"interiors\"><div class=\"block-head\"><h2>Interiors</h2><p>' + int.length + ' photos</p></div>' +\n        '<div class=\"grid\">' + tiles(int, ext.length) + '</div></section>';\n\n    if (isSignature) html += plansHtml() + tourHtml();\n    html += rebookHtml() + '</main>' +\n      '<footer class=\"foot\"><div class=\"wrap\"><div class=\"foot-top\"><a class=\"brand\" href=\"https://altusaerials.com/\"><img class=\"brand-mark\" src=\"' + esc(D.logo || \"/assets/images/logo-white.png\") + '\" alt=\"\" width=\"50\" height=\"32\"><span class=\"brand-text\">Altus Aerials</span></a>' +\n      '<nav><a href=\"https://altusaerials.com/\">Home</a><a href=\"https://altusaerials.com/services.html\">Services</a><a href=\"https://altusaerials.com/about.html\">About</a></nav></div>' +\n      '<div class=\"foot-bottom\"><span>Photos by Altus Aerials \u00b7 Chicago suburbs</span><span><a href=\"tel:+17087780566\">(708) 778-0566</a> \u00b7 <a href=\"mailto:hadi@altusaerials.com\">hadi@altusaerials.com</a></span></div></div></footer>' +\n      '<div class=\"dock\" id=\"dock\" aria-hidden=\"true\"><button class=\"btn btn-primary\" type=\"button\" data-act=\"zip\" tabindex=\"-1\">' + ICON.dl + '<span>Download all</span></button>' +\n      '<button class=\"btn btn-outline\" type=\"button\" data-act=\"share\" tabindex=\"-1\" aria-label=\"Share gallery\">' + ICON.share + '</button></div>' +\n      lightboxHtml() + '<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>';\n    $(\"#app\").innerHTML = html;\n  }\n\n  function plansHtml() {\n    var todo = D.floorPlans.some(function (f) { return f.placeholder; }) ?\n      '<p class=\"todo\"><b>For Hadi:</b><span>These are placeholder drawings. Drop the real floor plan files (PNG/JPG/PDF) in the upload page and they replace these automatically.</span></p>' : \"\";\n    return '<section class=\"block wrap\" id=\"floor-plans\"><div class=\"block-head\"><h2>Floor plans</h2><p>' + D.floorPlans.length + ' levels</p></div>' + todo +\n      '<div class=\"plans\">' + D.floorPlans.map(function (f, i) {\n        return '<div class=\"plan\"><button class=\"view\" type=\"button\" data-plan=\"' + i + '\" aria-label=\"Enlarge ' + esc(f.label) + '\"><img src=\"' + base + f.src + '\" alt=\"' + esc(f.label) + ' floor plan\" loading=\"lazy\"></button>' +\n          '<div class=\"plan-foot\"><div><strong>' + esc(f.label) + '</strong><small>' + esc(f.note || \"\") + '</small></div>' +\n          '<button class=\"mini\" type=\"button\" data-saveplan=\"' + i + '\">' + ICON.dl + 'Save</button></div></div>';\n      }).join(\"\") + '</div></section>';\n  }\n\n  function tourHtml() {\n    var t = D.tour, url = t.url || \"\";\n    var todo = t.placeholder ? '<p class=\"todo\"><b>For Hadi:</b><span>Paste the Zillow 3D Home tour link here (<code>tour.url</code>). Until then the buttons below point to a placeholder.</span></p>' : \"\";\n    return '<section class=\"block wrap\" id=\"tour\"><div class=\"block-head\"><h2>3D home tour</h2><p>Walk through from any phone</p></div>' + todo +\n      '<div class=\"tour\"><div class=\"tour-stage\">' +\n        (t.embed && url ? '<iframe src=\"' + esc(url) + '\" title=\"3D tour of ' + esc(D.address) + '\" allow=\"fullscreen; xr-spatial-tracking\" loading=\"lazy\"></iframe>' :\n        '<img src=\"' + thumb(int[0] || coverPhoto) + '\" alt=\"\"><div class=\"tour-cta\"><span class=\"ring\">' + ICON.cube + '</span>' +\n        '<a class=\"btn btn-light\" href=\"' + esc(url || \"#tour\") + '\" target=\"_blank\" rel=\"noopener\" data-act=\"tour\">' + ICON.ext + 'Open the 3D tour</a>' +\n        '<p>Opens in your browser. No app or login needed.</p></div>') +\n      '</div><div class=\"tour-link\"><code id=\"tour-url\">' + esc(url || \"https://www.zillow.com/view-imx/PLACEHOLDER-tour-link\") + '</code>' +\n        '<button class=\"mini\" type=\"button\" data-act=\"copytour\">' + ICON.copy + 'Copy link</button></div></div>' +\n      '<div class=\"explain\">' +\n        '<article><h3>What it is</h3><p>A walk-through of the whole home, built from 360\u00b0 photos taken in every room. Buyers move from room to room on their own, the same way they would at a showing, from their phone or laptop.</p></article>' +\n        '<article><h3>How to use it</h3><ol><li>Tap <b>Open the 3D tour</b>.</li><li>Drag to look around the room.</li><li>Tap a circle on the floor to step to that spot.</li><li>Use the floor plan or room list in the tour to jump to another room.</li></ol></article>' +\n        '<article><h3>Where to share it</h3><ul><li><b>MLS:</b> paste the link into your listing\\'s Virtual Tour field.</li><li><b>Zillow:</b> the tour can show on the Zillow listing itself. If it isn\\'t there once the listing is live, text Hadi and he\\'ll get it attached.</li><li><b>Buyers and sellers:</b> text or email the link. It opens in any browser.</li></ul>' +\n        '<p class=\"note\">Tap <b>Copy link</b> above to grab it.</p></article>' +\n      '</div></section>';\n  }\n\n  function rebookHtml() {\n    var pk = [[\"Overview\", 149, \"Exterior aerial photos\"], [\"Showcase\", 349, \"Aerial photos + video, full interiors\"], [\"Signature\", 499, \"Showcase + 3D tour + floor plans\"], [\"Summit\", 649, \"Signature + cinematic FPV fly-through\"]];\n    return '<section class=\"rebook\" id=\"book\"><div class=\"wrap\"><h2>Got another listing coming up?</h2>' +\n      '<p>Pick a package and a date. No account needed. Hadi confirms by text, usually the same day.</p>' +\n      '<div class=\"pkgs\">' + pk.map(function (p) {\n        return '<div class=\"pkg' + (p[0] === D.package ? \" current\" : \"\") + '\"><b>' + p[0] + '</b><span>$' + p[1] + '</span><small>' + p[2] + '</small></div>';\n      }).join(\"\") + '</div>' +\n      '<a class=\"btn btn-light\" href=\"' + esc(D.bookUrl) + '\" data-act=\"book\">' + ICON.cal + 'Book your next shoot</a></div></section>';\n  }\n\n  function lightboxHtml() {\n    return '<div class=\"lb\" id=\"lb\" hidden role=\"dialog\" aria-modal=\"true\" aria-label=\"Photo viewer\">' +\n      '<div class=\"lb-top\"><span class=\"lb-count\" id=\"lb-count\"></span><button class=\"icon-btn\" type=\"button\" data-act=\"close\" aria-label=\"Close\">' + ICON.x + '</button></div>' +\n      '<div class=\"lb-stage\" id=\"lb-stage\"><img id=\"lb-img\" alt=\"\"><button class=\"lb-nav lb-prev\" type=\"button\" data-act=\"prev\" aria-label=\"Previous photo\">' + ICON.l + '</button>' +\n      '<button class=\"lb-nav lb-next\" type=\"button\" data-act=\"next\" aria-label=\"Next photo\">' + ICON.r + '</button></div>' +\n      '<div class=\"lb-bottom\"><span class=\"lb-name\" id=\"lb-name\"></span><button class=\"icon-btn\" type=\"button\" data-act=\"save\">' + ICON.dl + 'Save photo</button></div></div>';\n  }\n\n  /* ---------- lightbox ---------- */\n  var lbList = [], lbIdx = 0, lastFocus = null;\n  function lbItems(kind) {\n    if (kind === \"plans\") return D.floorPlans.map(function (f) { return { src: base + f.src, name: f.label + \" floor plan\", file: f.file || (f.label + \".png\") }; });\n    return ext.concat(int).map(function (p) { return { src: full(p), name: fileName(p), file: fileName(p), id: p.id }; });\n  }\n  function openLb(kind, i) {\n    lbList = lbItems(kind); lbIdx = i; lastFocus = document.activeElement;\n    $(\"#lb\").hidden = false; document.documentElement.style.overflow = \"hidden\";\n    showLb(0); $(\"#lb [data-act=close]\").focus();\n  }\n  function showLb(dir) {\n    var it = lbList[lbIdx], img = $(\"#lb-img\");\n    img.style.opacity = \"0\"; img.style.transform = dir ? \"translateX(\" + (dir * 24) + \"px)\" : \"none\";\n    var pre = new Image(); pre.onload = function () { img.src = it.src; img.alt = it.name; img.style.opacity = \"1\"; img.style.transform = \"none\"; };\n    pre.src = it.src;\n    $(\"#lb-count\").textContent = (lbIdx + 1) + \" / \" + lbList.length;\n    $(\"#lb-name\").textContent = it.name;\n    [1, -1].forEach(function (d) { var n = lbList[(lbIdx + d + lbList.length) % lbList.length]; if (n) new Image().src = n.src; });\n    if (it.id) ping(\"view_photo\", { p: it.id });\n  }\n  function step(d) { if (lbList.length < 2) return; lbIdx = (lbIdx + d + lbList.length) % lbList.length; showLb(d); }\n  function closeLb() { $(\"#lb\").hidden = true; document.documentElement.style.overflow = \"\"; if (lastFocus) lastFocus.focus(); }\n\n  /* ---------- saving ---------- */\n  function fetchBlob(url) { return fetch(url, { mode: \"cors\" }).then(function (r) { if (!r.ok) throw new Error(r.status); return r.blob(); }); }\n  function saveBlob(blob, name) {\n    var a = document.createElement(\"a\"); a.href = URL.createObjectURL(blob); a.download = name;\n    document.body.appendChild(a); a.click(); setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 4000);\n  }\n  function saveOne(it) {\n    return fetchBlob(it.src).then(function (blob) {\n      var f = new File([blob], it.file, { type: blob.type || \"image/jpeg\" });\n      // Phones: the share sheet offers \"Save Image\" straight to the camera roll.\n      if (navigator.canShare && navigator.canShare({ files: [f] }) && matchMedia(\"(pointer: coarse)\").matches) {\n        return navigator.share({ files: [f] }).catch(function () {});\n      }\n      saveBlob(blob, it.file); toast(\"Saved \" + it.file);\n    }).then(function () { ping(\"download_photo\", { p: it.id || it.file }); })\n      .catch(function () { location.href = it.src + (it.src.indexOf(\"?\") < 0 ? \"?\" : \"&\") + \"dl=1\"; });\n  }\n\n  var zipBusy = false;\n  function loadJSZip() {\n    return window.JSZip ? Promise.resolve() : new Promise(function (ok, no) {\n      var s = document.createElement(\"script\"); s.src = \"https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js\";\n      s.onload = ok; s.onerror = no; document.head.appendChild(s);\n    });\n  }\n  function downloadAll() {\n    if (zipBusy) return;\n    ping(\"download_all\");\n    var zipName = D.address + \" - Altus Aerials.zip\";\n    if (D.zipUrl) { location.href = D.zipUrl; toast(\"Downloading \" + zipName); return; } // pre-built zip on R2 (production path)\n    zipBusy = true;\n    var btns = document.querySelectorAll(\"[data-act=zip]\");\n    var label = function (t) { btns.forEach(function (b) { b.disabled = !!t; b.querySelector(\"span\").textContent = t || (b.closest(\".dock\") ? \"Download all\" : \"Download all \" + D.photos.length + \" photos\"); }); };\n    label(\"Preparing\u2026 0%\");\n    loadJSZip().then(function () {\n      var zip = new JSZip(), done = 0;\n      var jobs = D.photos.map(function (p) {\n        return fetchBlob(full(p)).then(function (b) {\n          zip.file((p.kind === \"EXT\" ? \"Exteriors/\" : \"Interiors/\") + fileName(p), b);\n          label(\"Preparing\u2026 \" + Math.round(++done / D.photos.length * 100) + \"%\");\n        });\n      });\n      if (isSignature) D.floorPlans.forEach(function (f) { jobs.push(fetchBlob(base + f.src).then(function (b) { zip.file(\"Floor Plans/\" + (f.file || f.label + \".png\"), b); })); });\n      return Promise.all(jobs).then(function () { return zip.generateAsync({ type: \"blob\", compression: \"STORE\" }); });\n    }).then(function (blob) { saveBlob(blob, zipName); toast(\"Download started\"); })\n      .catch(function () { toast(\"Download didn't finish. Check your connection and try again.\"); })\n      .then(function () { zipBusy = false; label(\"\"); });\n  }\n\n  /* ---------- share ---------- */\n  function shareGallery() {\n    var url = D.shareUrl || location.href.split(\"#\")[0];\n    var data = { title: D.address + \" | Photos by Altus Aerials\", text: \"Photos for \" + D.address + \", by Altus Aerials\", url: url };\n    ping(\"share\");\n    if (navigator.share) { navigator.share(data).catch(function () {}); return; }\n    copy(url, \"Gallery link copied\");\n  }\n  function copy(text, msg) {\n    var done = function () { toast(msg); };\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text); done(); });\n    } else { fallbackCopy(text); done(); }\n  }\n  function fallbackCopy(text) {\n    var ta = document.createElement(\"textarea\"); ta.value = text; ta.setAttribute(\"readonly\", \"\"); ta.style.position = \"fixed\"; ta.style.opacity = \"0\";\n    document.body.appendChild(ta); ta.select(); try { document.execCommand(\"copy\"); } catch (e) {} ta.remove();\n  }\n\n  /* ---------- events ---------- */\n  function wire() {\n    document.addEventListener(\"click\", function (e) {\n      var t = e.target.closest(\"[data-i],[data-plan],[data-saveplan],[data-act]\"); if (!t) return;\n      if (t.dataset.i != null) return openLb(\"photos\", +t.dataset.i);\n      if (t.dataset.plan != null) return openLb(\"plans\", +t.dataset.plan);\n      if (t.dataset.saveplan != null) return saveOne(lbItems(\"plans\")[+t.dataset.saveplan]);\n      switch (t.dataset.act) {\n        case \"zip\": return downloadAll();\n        case \"share\": return shareGallery();\n        case \"close\": return closeLb();\n        case \"prev\": return step(-1);\n        case \"next\": return step(1);\n        case \"save\": return saveOne(lbList[lbIdx]);\n        case \"copytour\": ping(\"copy_tour\"); return copy($(\"#tour-url\").textContent, \"Tour link copied\");\n        case \"tour\": ping(\"open_tour\"); if (!D.tour.url) { e.preventDefault(); toast(\"Tour link coming soon\"); } return;\n        case \"book\": return ping(\"book_click\");\n      }\n    });\n    document.addEventListener(\"keydown\", function (e) {\n      if ($(\"#lb\").hidden) return;\n      if (e.key === \"Escape\") closeLb(); else if (e.key === \"ArrowRight\") step(1); else if (e.key === \"ArrowLeft\") step(-1);\n    });\n    // swipe: left/right to change photo, down to close\n    var sx = 0, sy = 0, st = $(\"#lb-stage\");\n    st.addEventListener(\"touchstart\", function (e) { sx = e.touches[0].clientX; sy = e.touches[0].clientY; }, { passive: true });\n    st.addEventListener(\"touchend\", function (e) {\n      var dx = e.changedTouches[0].clientX - sx, dy = e.changedTouches[0].clientY - sy;\n      if (Math.abs(dx) > 45 && Math.abs(dx) > Math.abs(dy)) step(dx < 0 ? 1 : -1);\n      else if (dy > 90 && Math.abs(dy) > Math.abs(dx)) closeLb();\n    }, { passive: true });\n    st.addEventListener(\"click\", function (e) { if (e.target === st && matchMedia(\"(pointer: coarse)\").matches === false) closeLb(); });\n\n    // sticky dock appears once the main action row scrolls away\n    var dock = $(\"#dock\");\n    if (\"IntersectionObserver\" in window) {\n      new IntersectionObserver(function (en) {\n        var show = !en[0].isIntersecting && en[0].boundingClientRect.top < 0;\n        dock.classList.toggle(\"show\", show); dock.setAttribute(\"aria-hidden\", show ? \"false\" : \"true\");\n        dock.querySelectorAll(\"button\").forEach(function (b) { b.tabIndex = show ? 0 : -1; });\n      }).observe($(\"#actions\"));\n      var chips = document.querySelectorAll(\".chip\");\n      var spy = new IntersectionObserver(function (en) {\n        en.forEach(function (x) {\n          if (!x.isIntersecting) return;\n          chips.forEach(function (c) {\n            var on = c.getAttribute(\"href\") === \"#\" + x.target.id; c.classList.toggle(\"active\", on);\n            if (on && c.scrollIntoView) c.parentNode.scrollTo({ left: c.offsetLeft - 16, behavior: \"smooth\" });\n          });\n        });\n      }, { rootMargin: \"-45% 0px -50% 0px\" });\n      document.querySelectorAll(\"main > section[id]\").forEach(function (s) { spy.observe(s); });\n    }\n  }\n\n  /* ---------- optional password gate ----------\n     Real galleries: the Worker sends only {locked:true, slug, address, api} until the\n     right password is posted back, so photo addresses never reach the browser early.\n     Prototype preview only: hash check in the page (look-and-feel demo, add #locked). */\n  function sha256(s) {\n    return crypto.subtle.digest(\"SHA-256\", new TextEncoder().encode(s)).then(function (b) {\n      return Array.from(new Uint8Array(b)).map(function (x) { return x.toString(16).padStart(2, \"0\"); }).join(\"\");\n    });\n  }\n  function gate(boot, unlock) {\n    var g = document.createElement(\"div\"); g.className = \"gate\";\n    g.innerHTML = '<form id=\"gate-form\"><h2>' + esc(boot.address) + '</h2>' +\n      (boot.cityLine ? '<p>' + esc(boot.cityLine) + '</p>' : '') +\n      '<p>This gallery is private until the listing goes live. Enter the password from Hadi\\'s text.</p>' +\n      '<label for=\"gate-pw\" class=\"sr\">Password</label><input id=\"gate-pw\" type=\"password\" autocomplete=\"off\" autocapitalize=\"none\" placeholder=\"Password\" required>' +\n      '<button class=\"btn btn-blue\" type=\"submit\">View photos</button><p class=\"err\" id=\"gate-err\" aria-live=\"polite\"></p>' +\n      (boot.passwordDemoOnHash ? '<p style=\"font-size:13px;opacity:.7\">Prototype password: saratoga</p>' : '') + '</form>';\n    document.body.appendChild(g);\n    var btn = g.querySelector(\"button\");\n    g.querySelector(\"form\").addEventListener(\"submit\", function (e) {\n      e.preventDefault();\n      var pw = g.querySelector(\"input\").value.trim();\n      btn.disabled = true;\n      unlock(pw).then(function (data) { g.remove(); start(data); }, function () {\n        btn.disabled = false;\n        $(\"#gate-err\").textContent = \"That password didn't match. Check the text from Hadi and try again.\";\n      });\n    });\n  }\n  function start(data) {\n    setup(data); render(); wire(); ping(\"open\");\n    if (location.hash && location.hash.length > 1) { var t = document.getElementById(location.hash.slice(1)); if (t) t.scrollIntoView(); }\n  }\n\n  var boot = JSON.parse(document.getElementById(\"gallery-data\").textContent);\n  if (boot.locked) {\n    gate(boot, function (pw) {\n      return fetch(boot.api + \"/api/g/\" + encodeURIComponent(boot.slug), {\n        method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ password: pw })\n      }).then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); });\n    });\n  } else if (boot.passwordHash && boot.passwordDemoOnHash && location.hash === \"#locked\") {\n    gate(boot, function (pw) {\n      return sha256(pw.toLowerCase()).then(function (h) { if (h !== boot.passwordHash) throw new Error(\"no\"); return boot; });\n    });\n  } else {\n    start(boot);\n  }\n})();\n"}, "/assets/gallery/og-default.jpg": {"type": "image/jpeg", "b64": true, "body": ""}, "/assets/images/logo-white.png": {"type": "image/png", "b64": true, "body": ""}, "/assets/images/favicon.png": {"type": "image/png", "b64": true, "body": ""}, "/assets/studio/studio.css": {"type": "text/css; charset=utf-8", "body": "/* Altus studio + rebook pages \u2014 same tokens as the main site */\n[hidden] { display: none !important; }\n:root {\n  --navy: #0b2545; --navy-deep: #071a33; --blue: #4c8dff; --blue-light: #8ec5ff;\n  --ink: #101828; --muted: #5b6474; --paper: #fff; --paper-soft: #f6f8fb; --line: #e4e8ef; --chip: #e9eef7;\n  --good: #0f7b4a; --good-bg: #e3f5ec; --warn: #8a5a00; --warn-bg: #fff4d6; --bad: #b42318; --bad-bg: #fde8e6;\n  --serif: \"Fraunces\", Georgia, serif; --sans: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --r: 14px; color-scheme: light;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--paper-soft); color: var(--ink); font: 16px/1.5 var(--sans); -webkit-font-smoothing: antialiased; }\nimg { max-width: 100%; display: block; }\nbutton, input, select, textarea { font: inherit; color: inherit; }\n:focus-visible { outline: 3px solid var(--blue); outline-offset: 2px; }\n.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n\n.bar { background: var(--navy); color: #fff; padding: 14px 16px calc(14px); padding-top: calc(14px + env(safe-area-inset-top, 0px)); }\n.bar .in { max-width: 1100px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }\n.brand { display: flex; align-items: center; gap: 10px; color: #fff; text-decoration: none; }\n.brand img { height: 32px; width: auto; }\n.brand-text { font: 400 20px/1 var(--serif); letter-spacing: .02em; }\n.studio-tag { font-size: 11px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--blue-light); border: 1px solid rgba(142,197,255,.45); border-radius: 999px; padding: 4px 9px; }\n.bar nav { display: flex; gap: 6px; }\n.bar nav a { color: #fff; text-decoration: none; font-size: 14px; font-weight: 600; padding: 8px 12px; border-radius: 999px; }\n.bar nav a[aria-current=\"page\"] { background: rgba(255,255,255,.12); }\n\nmain.page { max-width: 1100px; margin: 0 auto; padding: 22px 16px 120px; display: grid; gap: 18px; }\nh1 { margin: 0; font: 500 clamp(28px, 6vw, 38px)/1.15 var(--serif); color: var(--navy); text-wrap: balance; }\nh2 { margin: 0; font: 500 22px/1.2 var(--serif); color: var(--navy); }\n.lede { margin: 4px 0 0; color: var(--muted); max-width: 62ch; }\n.card { background: var(--paper); border: 1px solid var(--line); border-radius: var(--r); padding: 18px; display: grid; gap: 14px; min-width: 0; }\n.card-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; }\n.step { display: inline-grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; background: var(--navy); color: #fff; font-size: 13px; font-weight: 700; margin-right: 8px; vertical-align: 2px; }\n.muted { color: var(--muted); font-size: 14px; }\n\n.fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }\nlabel.f { display: grid; gap: 5px; font-size: 13px; font-weight: 600; color: var(--muted); min-width: 0; }\nlabel.f.wide { grid-column: 1 / -1; }\ninput[type=text], input[type=tel], input[type=email], input[type=date], input[type=url], input[type=password], select, textarea {\n  width: 100%; min-height: 46px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 10px; background: #fff; color: var(--ink); font-size: 16px; font-weight: 400;\n}\ntextarea { min-height: 120px; resize: vertical; line-height: 1.45; }\ninput:focus, select:focus, textarea:focus { border-color: var(--blue); outline: none; box-shadow: 0 0 0 3px rgba(76,141,255,.2); }\n\n.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 12px 22px; border-radius: 999px; border: 1px solid transparent;\n  font-weight: 600; font-size: 14px; letter-spacing: .03em; text-transform: uppercase; cursor: pointer; text-decoration: none; }\n.btn-primary { background: var(--navy); color: #fff; box-shadow: 0 8px 24px rgba(11,37,69,.22); }\n.btn-blue { background: var(--blue); color: #fff; }\n.btn-outline { background: #fff; border-color: var(--line); color: var(--ink); }\n.btn[disabled] { opacity: .55; cursor: not-allowed; box-shadow: none; }\n.btn svg { width: 18px; height: 18px; }\n.row { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }\n.link { background: none; border: 0; padding: 0; color: var(--blue); font-weight: 600; cursor: pointer; text-decoration: underline; text-underline-offset: 3px; font-size: 14px; }\n\n.pill { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: 999px; font-size: 12.5px; font-weight: 600; background: var(--chip); color: var(--ink); white-space: nowrap; }\n.pill.good { background: var(--good-bg); color: var(--good); } .pill.warn { background: var(--warn-bg); color: var(--warn); } .pill.bad { background: var(--bad-bg); color: var(--bad); }\n.note { padding: 12px 14px; border-radius: 10px; font-size: 14px; background: var(--warn-bg); color: var(--warn); }\n.note.good { background: var(--good-bg); color: var(--good); } .note.bad { background: var(--bad-bg); color: var(--bad); }\n\n/* choice cards (packages, time windows) */\n.choices { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }\n@media (min-width: 860px) { .choices.four { grid-template-columns: repeat(4, minmax(0, 1fr)); } }\n.choice { position: relative; display: grid; gap: 2px; padding: 14px; border: 1.5px solid var(--line); border-radius: 12px; background: #fff; cursor: pointer; }\n.choice input { position: absolute; opacity: 0; pointer-events: none; }\n.choice b { font-size: 15px; } .choice .price { font: 600 22px/1.2 var(--serif); color: var(--navy); }\n.choice small { color: var(--muted); font-size: 13px; line-height: 1.35; }\n.choice:has(input:checked) { border-color: var(--blue); background: #f2f7ff; box-shadow: 0 0 0 3px rgba(76,141,255,.18); }\n.choice:has(input:focus-visible) { outline: 3px solid var(--blue); outline-offset: 2px; }\n.windows { display: flex; flex-wrap: wrap; gap: 8px; }\n.windows .choice { padding: 10px 16px; border-radius: 999px; }\n\n/* upload */\n.drop { display: grid; place-items: center; gap: 8px; text-align: center; padding: 28px 16px; border: 2px dashed #b8c6dc; border-radius: var(--r); background: #f8fbff; color: var(--muted); cursor: pointer; }\n.drop.over { border-color: var(--blue); background: #eef4ff; }\n.drop b { color: var(--ink); font-size: 17px; }\n.drop svg { width: 34px; height: 34px; color: var(--blue); }\n.legend { display: flex; flex-wrap: wrap; gap: 8px 16px; font-size: 13.5px; color: var(--muted); }\n.ptiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 8px; }\n.pt { position: relative; border-radius: 10px; overflow: hidden; background: var(--chip); aspect-ratio: 3 / 2; border: 0; padding: 0; cursor: pointer; }\n.pt img { width: 100%; height: 100%; object-fit: cover; transition: opacity .15s, filter .15s; }\n.pt .name { position: absolute; left: 6px; bottom: 6px; padding: 2px 7px; border-radius: 999px; background: rgba(7,26,51,.75); color: #fff; font-size: 11px; font-weight: 600; }\n.pt.off img { opacity: .28; filter: grayscale(1); }\n.pt.off::after { content: \"Excluded\"; position: absolute; inset: 0; display: grid; place-items: center; color: var(--bad); font-weight: 700; font-size: 13px; letter-spacing: .04em; }\n.pt .tools { position: absolute; top: 5px; right: 5px; display: flex; gap: 4px; }\n.pt .tools span { display: inline-grid; place-items: center; min-width: 30px; height: 30px; padding: 0 7px; border-radius: 999px; background: rgba(255,255,255,.92); color: var(--navy); font-size: 11.5px; font-weight: 700; }\n.pt .tools span.on { background: var(--blue); color: #fff; }\n.pt.cover { box-shadow: 0 0 0 3px var(--blue); }\n.pt .kindwarn { position: absolute; left: 5px; top: 5px; background: var(--warn-bg); color: var(--warn); font-size: 11px; font-weight: 700; padding: 2px 7px; border-radius: 999px; }\n.plans-list { display: grid; gap: 10px; }\n.plan-row { display: grid; grid-template-columns: 96px minmax(0, 1fr) auto; gap: 12px; align-items: center; }\n.plan-row img { width: 96px; aspect-ratio: 4 / 3; object-fit: contain; background: #fff; border: 1px solid var(--line); border-radius: 8px; }\n.switch { display: flex; align-items: center; gap: 10px; font-weight: 600; cursor: pointer; }\n.switch input { width: 20px; height: 20px; accent-color: var(--navy); }\n.progress { height: 10px; border-radius: 999px; background: var(--chip); overflow: hidden; }\n.progress i { display: block; height: 100%; width: 0; background: var(--blue); transition: width .2s; }\n.sticky-go { position: sticky; bottom: 0; z-index: 5; background: rgba(244,246,250,.94); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);\n  padding: 12px 0 calc(12px + env(safe-area-inset-bottom, 0px)); border-top: 1px solid var(--line); }\n.done-link { word-break: break-all; font-weight: 600; }\n\n/* tables (activity) */\n.tabs { display: flex; gap: 6px; flex-wrap: wrap; }\n.tabs button { border: 0; background: var(--chip); padding: 8px 14px; border-radius: 999px; font-weight: 600; cursor: pointer; }\n.tabs button[aria-selected=\"true\"] { background: var(--navy); color: #fff; }\n.tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--r); background: #fff; }\ntable { width: 100%; border-collapse: collapse; font-size: 14px; }\nth, td { padding: 11px 12px; text-align: left; border-bottom: 1px solid var(--line); vertical-align: top; white-space: nowrap; }\nth { font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); background: var(--paper-soft); }\ntd.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }\ntd .sub { display: block; color: var(--muted); font-size: 12.5px; }\ntr:last-child td { border-bottom: 0; }\n.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; }\n.stat { background: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 14px; }\n.stat b { display: block; font: 500 30px/1.1 var(--serif); color: var(--navy); font-variant-numeric: tabular-nums; }\n.stat span { color: var(--muted); font-size: 13px; }\n\n/* key gate */\n.gatebox { max-width: 420px; margin: 8vh auto 0; }\nfooter.f { text-align: center; color: var(--muted); font-size: 13px; padding: 10px 16px 30px; }\n@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }\n"}, "/assets/studio/studio.js": {"type": "text/javascript; charset=utf-8", "body": "/* Shared helpers for studio pages: API base, passphrase, fetch wrapper. */\n(function () {\n  var API = (window.ALTUS_API || location.origin).replace(/\\/$/, \"\");\n  function getKey() { try { return localStorage.getItem(\"altus_studio_key\") || \"\"; } catch (e) { return \"\"; } }\n  function setKey(k) { try { localStorage.setItem(\"altus_studio_key\", k); localStorage.setItem(\"altus_owner\", \"1\"); } catch (e) {} }\n  function api(path, opts) {\n    opts = opts || {};\n    var headers = Object.assign({ authorization: \"Bearer \" + getKey() }, opts.headers || {});\n    return fetch(API + path, Object.assign({}, opts, { headers: headers })).then(function (r) {\n      return r.text().then(function (t) {\n        var body; try { body = t ? JSON.parse(t) : {}; } catch (e) { body = { error: t }; }\n        if (!r.ok) { var err = new Error(body.error || (\"Error \" + r.status)); err.status = r.status; throw err; }\n        return body;\n      });\n    });\n  }\n  /* Shows a passphrase box until the Worker accepts it, then calls ready(info). */\n  function requireKey(mount, ready) {\n    function tryKey(k, quiet) {\n      if (!k) return Promise.reject(new Error(\"empty\"));\n      setKey(k);\n      return api(\"/api/studio/whoami\").then(ready, function (e) {\n        try { localStorage.removeItem(\"altus_studio_key\"); } catch (x) {}\n        if (!quiet) throw e; else throw e;\n      });\n    }\n    function show() {\n      mount.innerHTML = '<div class=\"card gatebox\"><h1>Studio</h1><p class=\"lede\">Enter your studio passphrase. This device will remember it.</p>' +\n        '<form id=\"keyform\" class=\"fields\"><label class=\"f wide\">Passphrase<input id=\"studio-key\" type=\"password\" autocomplete=\"current-password\" required></label>' +\n        '<button class=\"btn btn-primary\" type=\"submit\">Unlock</button><p id=\"key-err\" class=\"muted\" aria-live=\"polite\"></p></form></div>';\n      document.getElementById(\"keyform\").addEventListener(\"submit\", function (e) {\n        e.preventDefault();\n        tryKey(document.getElementById(\"studio-key\").value.trim()).catch(function (err) {\n          document.getElementById(\"key-err\").textContent = err.status === 401 ? \"That passphrase didn't work.\" : \"Couldn't reach the server. Check your connection.\";\n        });\n      });\n    }\n    var k = getKey();\n    if (k) tryKey(k, true).catch(show); else show();\n  }\n  function esc(s) { return String(s == null ? \"\" : s).replace(/[&<>\"']/g, function (c) { return { \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]; }); }\n  window.Studio = { API: API, api: api, requireKey: requireKey, esc: esc, key: getKey };\n})();\n"}, "/assets/studio/upload.js": {"type": "text/javascript; charset=utf-8", "body": "/* Studio \u2192 Deliver a shoot.\n   Pick the shoot, drop the edited folder, curate, publish. Photos are resized in the\n   browser (1920px, JPEG 80) before upload, so a 400 MB folder uploads as ~15 MB. */\n(function () {\n  \"use strict\";\n  var S = window.Studio, esc = S.esc;\n  var PACKAGES = [[\"Overview\", 149], [\"Showcase\", 349], [\"Signature\", 499], [\"Summit\", 649]];\n  var MAX_EDGE = 1920, QUALITY = 0.8, THUMB_EDGE = 800, THUMB_Q = 0.72;\n  var st = { info: null, shoots: [], photos: [], cover: null, plans: [], busy: false, lastSlug: null };\n  var app = document.getElementById(\"app\");\n\n  S.requireKey(app, function (info) { st.info = info; renderShell(); loadShoots(); });\n\n  /* ---------- layout ---------- */\n  function renderShell() {\n    app.innerHTML =\n      '<div><h1>Deliver a shoot</h1><p class=\"lede\">Pick the shoot, drop the edited folder, tap any photo you want to leave out, then publish. You get a link and a text ready to send.</p></div>' +\n\n      '<section class=\"card\" aria-labelledby=\"s1\"><div class=\"card-head\"><h2 id=\"s1\"><span class=\"step\">1</span>Shoot</h2><span id=\"fp-status\"></span></div>' +\n        '<label class=\"f wide\" id=\"shoot-pick-wrap\" hidden>From Flightpath<select id=\"shoot-pick\"><option value=\"\">Choose a shoot\u2026</option></select></label>' +\n        '<div class=\"fields\">' +\n          '<label class=\"f wide\">Property address<input id=\"f-address\" type=\"text\" placeholder=\"3524 Saratoga Ave\" autocomplete=\"off\" required></label>' +\n          '<label class=\"f\">City<input id=\"f-city\" type=\"text\" placeholder=\"Downers Grove\" autocomplete=\"off\"></label>' +\n          '<label class=\"f\">State<input id=\"f-state\" type=\"text\" value=\"IL\" maxlength=\"2\" autocomplete=\"off\"></label>' +\n          '<label class=\"f\">Package<select id=\"f-package\">' + PACKAGES.map(function (p) { return '<option value=\"' + p[0] + '\">' + p[0] + ' ($' + p[1] + ')</option>'; }).join(\"\") + '</select></label>' +\n          '<label class=\"f\">Shoot date<input id=\"f-date\" type=\"date\"></label>' +\n          '<label class=\"f\">Agent name<input id=\"f-agent\" type=\"text\" autocomplete=\"off\"></label>' +\n          '<label class=\"f\">Agent mobile<input id=\"f-phone\" type=\"tel\" autocomplete=\"off\" placeholder=\"(708) 555-0123\"></label>' +\n          '<label class=\"f\">Agent email (optional)<input id=\"f-email\" type=\"email\" autocomplete=\"off\"></label>' +\n        '</div></section>' +\n\n      '<section class=\"card\" aria-labelledby=\"s2\"><div class=\"card-head\"><h2 id=\"s2\"><span class=\"step\">2</span>Photos</h2><span class=\"muted\" id=\"photo-count\"></span></div>' +\n        '<label class=\"drop\" id=\"drop\" for=\"pick-folder\">' +\n          '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><path d=\"M12 11v6m0-6-2.5 2.5M12 11l2.5 2.5\"/></svg>' +\n          '<b>Drop the shoot folder here</b><span>or tap to choose it. JPG and PNG. Anything inside an \"MLS\" subfolder is skipped.</span></label>' +\n        '<input id=\"pick-folder\" type=\"file\" webkitdirectory directory multiple hidden>' +\n        '<div class=\"row\"><button class=\"link\" type=\"button\" id=\"pick-files-btn\">Choose individual photos instead</button><input id=\"pick-files\" type=\"file\" accept=\"image/jpeg,image/png\" multiple hidden></div>' +\n        '<div class=\"legend\" id=\"legend\" hidden><span><b>Tap</b> a photo to exclude or include it</span><span><b>\u2605</b> sets the cover</span><span><b>EXT/INT</b> switches its section</span></div>' +\n        '<div id=\"tiles\"></div></section>' +\n\n      '<section class=\"card\" aria-labelledby=\"s3\" id=\"sig-card\"><div class=\"card-head\"><h2 id=\"s3\"><span class=\"step\">3</span>Floor plans and 3D tour</h2><span class=\"muted\">Signature and Summit</span></div>' +\n        '<p class=\"muted\" style=\"margin:0\">Export the floor plans from the Zillow 3D Home app as PNG or JPG and drop them here, then paste the tour link from the same app.</p>' +\n        '<label class=\"drop\" id=\"plan-drop\" for=\"pick-plans\" style=\"padding:18px\"><b>Drop floor plan images</b><span>PNG or JPG, one per level</span></label>' +\n        '<input id=\"pick-plans\" type=\"file\" accept=\"image/png,image/jpeg\" multiple hidden>' +\n        '<div class=\"plans-list\" id=\"plans\"></div>' +\n        '<label class=\"f wide\">3D tour link<input id=\"f-tour\" type=\"url\" placeholder=\"https://www.zillow.com/view-imx/\u2026\" autocomplete=\"off\"></label>' +\n      '</section>' +\n\n      '<section class=\"card\" aria-labelledby=\"s4\"><h2 id=\"s4\"><span class=\"step\" id=\"s4n\">4</span>Privacy</h2>' +\n        '<label class=\"switch\"><input type=\"checkbox\" id=\"f-lock\"> Password-protect this gallery (pre-listing)</label>' +\n        '<label class=\"f\" id=\"pw-wrap\" hidden>Password for the agent<input id=\"f-pw\" type=\"text\" autocomplete=\"off\" placeholder=\"e.g. saratoga\"></label>' +\n        '<p class=\"muted\" style=\"margin:0\">The password goes in the text automatically. Link previews show the Altus logo instead of the house while it\\'s locked.</p>' +\n      '</section>' +\n\n      '<section class=\"card\" id=\"result\" hidden aria-live=\"polite\"></section>' +\n\n      '<div class=\"sticky-go\"><div class=\"row\" style=\"justify-content:space-between\">' +\n        '<div style=\"flex:1 1 220px;min-width:0\"><div class=\"progress\" id=\"prog\" hidden><i></i></div><p class=\"muted\" id=\"status\" style=\"margin:6px 0 0\">Add photos to get started.</p></div>' +\n        '<button class=\"btn btn-primary\" type=\"button\" id=\"publish\" disabled>Publish gallery</button></div></div>';\n\n    wire();\n    syncPackage();\n    var d = new Date(); document.getElementById(\"f-date\").value = d.toISOString().slice(0, 10);\n  }\n\n  function loadShoots() {\n    var badge = document.getElementById(\"fp-status\");\n    S.api(\"/api/studio/shoots\").then(function (r) {\n      st.shoots = (r && r.shoots) || [];\n      if (r.error) { badge.innerHTML = '<span class=\"pill bad\" title=\"' + esc(r.error) + '\">Flightpath error: ' + esc(r.error) + '</span>'; return; }\n      if (!r.connected) { badge.innerHTML = '<span class=\"pill warn\">Flightpath not connected yet: fill in by hand</span>'; return; }\n      badge.innerHTML = '<span class=\"pill good\">Flightpath connected</span>';\n      if (!st.shoots.length) return;\n      var sel = document.getElementById(\"shoot-pick\");\n      st.shoots.forEach(function (s, i) { var o = document.createElement(\"option\"); o.value = i; o.textContent = s.date + \" \u00b7 \" + s.address + (s.agentName ? \" \u00b7 \" + s.agentName : \"\") + (s.package ? \" \u00b7 \" + s.package : \"\"); sel.appendChild(o); });\n      document.getElementById(\"shoot-pick-wrap\").hidden = false;\n    }, function () { badge.innerHTML = '<span class=\"pill warn\">Couldn\\'t load Flightpath shoots</span>'; });\n  }\n\n  /* ---------- events ---------- */\n  function $(id) { return document.getElementById(id); }\n  function wire() {\n    $(\"shoot-pick\").addEventListener(\"change\", function () {\n      var s = st.shoots[this.value]; if (!s) return;\n      $(\"f-address\").value = s.address || \"\"; $(\"f-city\").value = s.city || \"\"; $(\"f-state\").value = s.state || \"IL\";\n      if (s.package) $(\"f-package\").value = s.package; $(\"f-date\").value = s.date || \"\";\n      $(\"f-agent\").value = s.agentName || \"\"; $(\"f-phone\").value = s.agentPhone || \"\"; $(\"f-email\").value = s.agentEmail || \"\";\n      syncPackage(); validate();\n    });\n    $(\"f-package\").addEventListener(\"change\", syncPackage);\n    $(\"f-address\").addEventListener(\"input\", validate);\n    $(\"f-lock\").addEventListener(\"change\", function () { $(\"pw-wrap\").hidden = !this.checked; if (this.checked) $(\"f-pw\").focus(); });\n    $(\"pick-folder\").addEventListener(\"change\", function () { addFiles(Array.from(this.files).map(function (f) { return { file: f, path: f.webkitRelativePath || f.name }; })); this.value = \"\"; });\n    $(\"pick-files-btn\").addEventListener(\"click\", function () { $(\"pick-files\").click(); });\n    $(\"pick-files\").addEventListener(\"change\", function () { addFiles(Array.from(this.files).map(function (f) { return { file: f, path: f.name }; })); this.value = \"\"; });\n    $(\"pick-plans\").addEventListener(\"change\", function () { addPlans(Array.from(this.files)); this.value = \"\"; });\n    dropZone($(\"drop\"), function (list) { addFiles(list); });\n    dropZone($(\"plan-drop\"), function (list) { addPlans(list.map(function (x) { return x.file; })); });\n    $(\"tiles\").addEventListener(\"click\", onTile);\n    $(\"plans\").addEventListener(\"click\", function (e) {\n      var b = e.target.closest(\"[data-rm]\"); if (!b) return;\n      var p = st.plans.splice(+b.dataset.rm, 1)[0]; if (p) URL.revokeObjectURL(p.url); renderPlans();\n    });\n    $(\"plans\").addEventListener(\"input\", function (e) { var i = e.target.dataset.label; if (i != null) st.plans[+i].label = e.target.value; });\n    $(\"publish\").addEventListener(\"click\", publish);\n  }\n  function syncPackage() {\n    var sig = /Signature|Summit/.test($(\"f-package\").value);\n    $(\"sig-card\").hidden = !sig; $(\"s4n\").textContent = sig ? \"4\" : \"3\";\n  }\n  function dropZone(el, cb) {\n    [\"dragenter\", \"dragover\"].forEach(function (t) { el.addEventListener(t, function (e) { e.preventDefault(); el.classList.add(\"over\"); }); });\n    [\"dragleave\", \"drop\"].forEach(function (t) { el.addEventListener(t, function () { el.classList.remove(\"over\"); }); });\n    el.addEventListener(\"drop\", function (e) {\n      e.preventDefault();\n      var items = e.dataTransfer.items, entries = [];\n      if (items && items.length && items[0].webkitGetAsEntry) {\n        for (var i = 0; i < items.length; i++) { var en = items[i].webkitGetAsEntry(); if (en) entries.push(en); }\n        walk(entries).then(cb);\n      } else cb(Array.from(e.dataTransfer.files).map(function (f) { return { file: f, path: f.name }; }));\n    });\n  }\n  function walk(entries) {\n    var out = [];\n    function visit(entry, prefix) {\n      if (entry.isFile) return new Promise(function (ok) { entry.file(function (f) { out.push({ file: f, path: prefix + f.name }); ok(); }, ok); });\n      if (entry.isDirectory) {\n        var reader = entry.createReader(), all = [];\n        return new Promise(function (ok) {\n          (function more() {\n            reader.readEntries(function (batch) {\n              if (!batch.length) return Promise.all(all.map(function (c) { return visit(c, prefix + entry.name + \"/\"); })).then(ok);\n              all = all.concat(Array.from(batch)); more();\n            }, ok);\n          })();\n        });\n      }\n      return Promise.resolve();\n    }\n    return Promise.all(entries.map(function (e) { return visit(e, \"\"); })).then(function () { return out; });\n  }\n\n  /* ---------- photos ---------- */\n  function classify(path, name) {\n    var m = name.match(/\\((EXT|INT)\\)\\s*Image\\s*(\\d+)/i);\n    if (m) return { kind: m[1].toUpperCase(), n: +m[2], sure: true };\n    var num = (name.match(/(\\d+)/) || [])[1];\n    var low = path.toLowerCase();\n    if (/(^|\\/)interior/.test(low) || /\\b(kitchen|bath|bed|living|dining|closet|hall|laundry|basement)/.test(low)) return { kind: \"INT\", n: num ? +num : 999, sure: true };\n    if (/(^|\\/)exterior/.test(low) || /sunset|twilight|dusk|aerial|drone/.test(low)) return { kind: \"EXT\", n: num ? +num : (/sunset|twilight|dusk/.test(low) ? 0 : 999), sure: true };\n    return { kind: \"EXT\", n: num ? +num : 999, sure: false };\n  }\n  function addFiles(list) {\n    var seen = {}; st.photos.forEach(function (p) { seen[p.file.name + p.file.size] = 1; });\n    var added = 0, skipped = 0;\n    list.forEach(function (x) {\n      var name = x.file.name;\n      if (!/\\.(jpe?g|png)$/i.test(name) || name.charAt(0) === \".\") return;\n      if (/(^|\\/)mls\\//i.test(x.path)) { skipped++; return; }\n      if (seen[name + x.file.size]) return; seen[name + x.file.size] = 1;\n      var c = classify(x.path, name);\n      st.photos.push({ file: x.file, name: name, kind: c.kind, n: c.n, sure: c.sure, off: false, preview: null, uid: Math.random().toString(36).slice(2) });\n      added++;\n    });\n    st.photos.sort(function (a, b) { return (a.kind === b.kind ? 0 : a.kind === \"EXT\" ? -1 : 1) || a.n - b.n || a.name.localeCompare(b.name); });\n    if (!st.cover || st.photos.indexOf(st.cover) < 0) st.cover = st.photos.filter(function (p) { return p.kind === \"EXT\"; })[0] || st.photos[0] || null;\n    renderTiles(); makePreviews(); validate();\n    if (skipped) setStatus(added + \" photos added. Skipped \" + skipped + \" in the MLS folder.\");\n  }\n  function makePreviews() {\n    var queue = st.photos.filter(function (p) { return !p.preview && !p.pending; });\n    var running = 0;\n    function next() {\n      if (!queue.length || running >= 3) return;\n      var p = queue.shift(); p.pending = true; running++;\n      createImageBitmap(p.file, { resizeWidth: 360, resizeQuality: \"medium\" }).then(function (bmp) {\n        var c = document.createElement(\"canvas\"); c.width = bmp.width; c.height = bmp.height; c.getContext(\"2d\").drawImage(bmp, 0, 0); bmp.close();\n        return new Promise(function (ok) { c.toBlob(ok, \"image/jpeg\", 0.7); });\n      }).then(function (b) {\n        p.preview = URL.createObjectURL(b);\n        var img = document.querySelector('[data-uid=\"' + p.uid + '\"] img'); if (img) img.src = p.preview;\n      }).catch(function () {}).then(function () { running--; next(); });\n      next();\n    }\n    next();\n  }\n  function tileHtml(p) {\n    var cls = \"pt\" + (p.off ? \" off\" : \"\") + (p === st.cover ? \" cover\" : \"\");\n    return '<button type=\"button\" class=\"' + cls + '\" data-uid=\"' + p.uid + '\" aria-pressed=\"' + (!p.off) + '\" aria-label=\"' + esc(p.name) + (p.off ? \", excluded\" : \", included\") + '\">' +\n      '<img alt=\"\" src=\"' + (p.preview || \"data:image/gif;base64,R0lGODlhAQABAAAAACw=\") + '\">' +\n      (!p.sure ? '<span class=\"kindwarn\">Check section</span>' : '') +\n      '<span class=\"tools\"><span data-k=\"kind\" role=\"button\" aria-label=\"Switch section\">' + p.kind + '</span><span data-k=\"cover\" class=\"' + (p === st.cover ? \"on\" : \"\") + '\" role=\"button\" aria-label=\"Make cover\">\u2605</span></span>' +\n      '<span class=\"name\">' + esc(p.name.replace(/\\.(jpe?g|png)$/i, \"\")) + '</span></button>';\n  }\n  function renderTiles() {\n    var ext = st.photos.filter(function (p) { return p.kind === \"EXT\"; }), int = st.photos.filter(function (p) { return p.kind === \"INT\"; });\n    var sec = function (title, list) { return list.length ? '<h3 style=\"margin:16px 0 8px;font-size:15px\">' + title + ' <span class=\"muted\">' + list.filter(function (p) { return !p.off; }).length + ' of ' + list.length + '</span></h3><div class=\"ptiles\">' + list.map(tileHtml).join(\"\") + '</div>' : \"\"; };\n    $(\"tiles\").innerHTML = sec(\"Exteriors\", ext) + sec(\"Interiors\", int);\n    $(\"legend\").hidden = !st.photos.length;\n    var on = st.photos.filter(function (p) { return !p.off; }).length;\n    $(\"photo-count\").textContent = st.photos.length ? on + \" of \" + st.photos.length + \" photos included\" : \"\";\n  }\n  function onTile(e) {\n    var t = e.target.closest(\".pt\"); if (!t || st.busy) return;\n    var p = st.photos.filter(function (x) { return x.uid === t.dataset.uid; })[0]; if (!p) return;\n    var k = e.target.closest(\"[data-k]\");\n    if (k && k.dataset.k === \"cover\") { st.cover = p; p.off = false; }\n    else if (k && k.dataset.k === \"kind\") { p.kind = p.kind === \"EXT\" ? \"INT\" : \"EXT\"; p.sure = true; st.photos.sort(function (a, b) { return (a.kind === b.kind ? 0 : a.kind === \"EXT\" ? -1 : 1) || a.n - b.n; }); }\n    else {\n      p.off = !p.off;\n      if (p.off && p === st.cover) st.cover = st.photos.filter(function (x) { return !x.off && x.kind === \"EXT\"; })[0] || st.photos.filter(function (x) { return !x.off; })[0] || null;\n    }\n    renderTiles(); validate();\n  }\n\n  /* ---------- floor plans ---------- */\n  var LEVELS = [\"Main level\", \"Second level\", \"Lower level\", \"Third level\"];\n  function addPlans(files) {\n    files.filter(function (f) { return /\\.(png|jpe?g)$/i.test(f.name); }).forEach(function (f) {\n      var base = f.name.replace(/\\.[^.]+$/, \"\").replace(/[_-]+/g, \" \").replace(/\\s+/g, \" \").trim();\n      var generic = !/[a-z]{3}/i.test(base) || /^(img|image|screenshot|photo|scan|download)\\b/i.test(base);\n      st.plans.push({ file: f, url: URL.createObjectURL(f), label: generic ? (LEVELS[st.plans.length] || (\"Floor plan \" + (st.plans.length + 1))) : base.slice(0, 40) });\n    });\n    renderPlans();\n  }\n  function renderPlans() {\n    $(\"plans\").innerHTML = st.plans.map(function (p, i) {\n      return '<div class=\"plan-row\"><img src=\"' + p.url + '\" alt=\"\"><label class=\"f\">Label<input type=\"text\" data-label=\"' + i + '\" value=\"' + esc(p.label) + '\"></label>' +\n        '<button class=\"btn btn-outline\" type=\"button\" data-rm=\"' + i + '\" style=\"min-height:40px;padding:8px 14px\">Remove</button></div>';\n    }).join(\"\");\n  }\n\n  /* ---------- publish ---------- */\n  function setStatus(t, cls) { var s = $(\"status\"); s.textContent = t; s.style.color = cls === \"bad\" ? \"var(--bad)\" : \"\"; }\n  function setProg(f) { var p = $(\"prog\"); p.hidden = f == null; if (f != null) p.firstChild.style.width = Math.round(f * 100) + \"%\"; }\n  function validate() {\n    var n = st.photos.filter(function (p) { return !p.off; }).length;\n    var ok = n > 0 && $(\"f-address\").value.trim();\n    $(\"publish\").disabled = !ok || st.busy;\n    if (!st.busy) setStatus(!st.photos.length ? \"Add photos to get started.\" : !$(\"f-address\").value.trim() ? \"Add the property address.\" : n + \" photos ready to publish.\");\n  }\n  function slugify(s) { return s.toLowerCase().replace(/&/g, \" and \").replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\").slice(0, 50) || \"gallery\"; }\n  function safeName(s) { return s.replace(/[^A-Za-z0-9 ._()-]+/g, \" \").replace(/\\s+/g, \" \").trim().slice(0, 100) || \"Gallery\"; }\n  function toBlob(canvas, q) { return new Promise(function (ok) { canvas.toBlob(ok, \"image/jpeg\", q); }); }\n  function scaleTo(src, w, h, edge) {\n    var s = Math.min(1, edge / Math.max(w, h)), c = document.createElement(\"canvas\");\n    c.width = Math.round(w * s); c.height = Math.round(h * s);\n    var ctx = c.getContext(\"2d\"); ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = \"high\"; ctx.drawImage(src, 0, 0, c.width, c.height);\n    return c;\n  }\n  function put(key, blob, type, fileName, tries) {\n    tries = tries || 0;\n    return fetch(S.API + \"/api/studio/file?key=\" + encodeURIComponent(key), {\n      method: \"PUT\", body: blob, headers: { authorization: \"Bearer \" + S.key(), \"content-type\": type, \"x-file-name\": fileName }\n    }).then(function (r) {\n      if (r.ok) return; if (r.status === 401) throw new Error(\"Your studio passphrase stopped working. Reload and unlock again.\");\n      throw new Error(\"Upload failed (\" + r.status + \")\");\n    }).catch(function (e) { if (tries < 2 && !/passphrase/.test(e.message)) return new Promise(function (ok) { setTimeout(ok, 1200 * (tries + 1)); }).then(function () { return put(key, blob, type, fileName, tries + 1); }); throw e; });\n  }\n\n  function publish() {\n    if (st.busy) return;\n    var address = $(\"f-address\").value.trim();\n    var pkg = $(\"f-package\").value, sig = /Signature|Summit/.test(pkg);\n    var lock = $(\"f-lock\").checked, pw = $(\"f-pw\").value.trim();\n    if (lock && !pw) { setStatus(\"Type a password, or switch password protection off.\", \"bad\"); $(\"f-pw\").focus(); return; }\n    var tour = sig ? $(\"f-tour\").value.trim() : \"\";\n    if (tour && !/^https:\\/\\//i.test(tour)) { setStatus(\"The 3D tour link should start with https://\", \"bad\"); $(\"f-tour\").focus(); return; }\n\n    st.busy = true; $(\"publish\").disabled = true; $(\"result\").hidden = true;\n    var inc = st.photos.filter(function (p) { return !p.off; });\n    var ext = inc.filter(function (p) { return p.kind === \"EXT\"; }), int = inc.filter(function (p) { return p.kind === \"INT\"; });\n    var ordered = ext.concat(int), seq = 0;\n    ordered.forEach(function (p) { seq++; p.outN = seq; p.outId = p.kind.toLowerCase() + \"-\" + String(seq).padStart(2, \"0\"); });\n    var prefix = \"g/\" + slugify(address) + \"-\" + (crypto.randomUUID ? crypto.randomUUID().replace(/-/g, \"\").slice(0, 14) : Math.random().toString(36).slice(2, 16));\n    var zip = new JSZip(), meta = [], inflight = [], total = ordered.length * 2 + st.plans.length + 2, done = 0;\n    var tick = function () { done++; setProg(done / total); };\n    var plansSel = sig ? st.plans.slice() : [];\n    var zipName = safeName(address) + \" - Altus Aerials.zip\";\n    setProg(0);\n\n    function limit(p) { inflight.push(p); p.then(function () { inflight.splice(inflight.indexOf(p), 1); }, function () {}); return inflight.length >= 4 ? Promise.race(inflight).catch(function () {}) : Promise.resolve(); }\n\n    var chain = Promise.resolve();\n    ordered.forEach(function (p, i) {\n      chain = chain.then(function () {\n        setStatus(\"Resizing and uploading photo \" + (i + 1) + \" of \" + ordered.length + \"\u2026\");\n        return createImageBitmap(p.file);\n      }).then(function (bmp) {\n        var big = scaleTo(bmp, bmp.width, bmp.height, MAX_EDGE); bmp.close();\n        var small = scaleTo(big, big.width, big.height, THUMB_EDGE);\n        return Promise.all([toBlob(big, QUALITY), toBlob(small, THUMB_Q), big.width, big.height, small.width, small.height]);\n      }).then(function (r) {\n        var fname = \"(\" + p.kind + \") Image \" + p.outN + \".jpg\";\n        zip.file((p.kind === \"EXT\" ? \"Exteriors/\" : \"Interiors/\") + fname, r[0]);\n        meta.push({ id: p.outId, kind: p.kind, n: p.outN, tw: r[4], th: r[5] });\n        return limit(Promise.all([\n          put(prefix + \"/full/\" + p.outId + \".jpg\", r[0], \"image/jpeg\", fname).then(tick),\n          put(prefix + \"/thumb/\" + p.outId + \".jpg\", r[1], \"image/jpeg\", fname).then(tick)\n        ]));\n      });\n    });\n    var planMeta = [];\n    chain = chain.then(function () {\n      return Promise.all(plansSel.map(function (pl, i) {\n        var isPng = /png$/i.test(pl.file.type || pl.file.name), ext2 = isPng ? \"png\" : \"jpg\";\n        var prep = pl.file.size <= 8e6 ? Promise.resolve(pl.file) :\n          createImageBitmap(pl.file).then(function (b) { var c = scaleTo(b, b.width, b.height, 2400); b.close(); isPng = false; ext2 = \"jpg\"; return toBlob(c, 0.9); });\n        return prep.then(function (blob) {\n          var dl = safeName(pl.label + \" Floor Plan\") + \".\" + ext2, key = \"plans/plan-\" + (i + 1) + \".\" + ext2;\n          zip.file(\"Floor Plans/\" + dl, blob);\n          planMeta.push({ label: pl.label, src: key, file: dl, i: i });\n          return put(prefix + \"/\" + key, blob, isPng ? \"image/png\" : \"image/jpeg\", dl).then(tick);\n        });\n      }));\n    }).then(function () { return Promise.all(inflight); }).then(function () {\n      setStatus(\"Building the download-all zip\u2026\");\n      return zip.generateAsync({ type: \"blob\", compression: \"STORE\" });\n    }).then(function (zblob) {\n      tick(); setStatus(\"Uploading the zip (\" + (zblob.size / 1048576).toFixed(1) + \" MB)\u2026\");\n      return put(prefix + \"/zip/\" + zipName, zblob, \"application/zip\", zipName);\n    }).then(function () {\n      tick(); setStatus(\"Publishing\u2026\");\n      planMeta.sort(function (a, b) { return a.i - b.i; });\n      var city = $(\"f-city\").value.trim(), state = $(\"f-state\").value.trim().toUpperCase();\n      return S.api(\"/api/studio/publish\", {\n        method: \"POST\", headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify({\n          address: address, cityLine: [city, state].filter(Boolean).join(\", \"), package: pkg, shootDate: $(\"f-date\").value,\n          agentName: $(\"f-agent\").value.trim(), agentPhone: $(\"f-phone\").value.trim(), agentEmail: $(\"f-email\").value.trim(),\n          flightpathId: (st.shoots[$(\"shoot-pick\").value] || {}).id || null,\n          prefix: prefix, photos: meta, cover: st.cover && !st.cover.off ? st.cover.outId : meta[0].id,\n          floorPlans: planMeta.map(function (m) { return { label: m.label, src: m.src, file: m.file }; }),\n          tourUrl: tour, zipFile: \"zip/\" + zipName, password: lock ? pw : \"\",\n          replaceSlug: $(\"f-replace\") && $(\"f-replace\").checked ? st.lastSlug : null\n        })\n      });\n    }).then(function (res) {\n      setProg(1); setStatus(\"Published.\");\n      st.lastSlug = res.slug;\n      showResult(res, { address: address, sig: sig, pw: lock ? pw : \"\", agent: $(\"f-agent\").value.trim(), phone: $(\"f-phone\").value.trim(), tour: !!tour, plans: planMeta.length });\n    }).catch(function (e) {\n      setProg(null); setStatus((e && e.message) || \"Something went wrong. Check your connection and publish again.\", \"bad\");\n    }).then(function () { st.busy = false; $(\"publish\").disabled = !st.photos.some(function (p) { return !p.off; }); });\n  }\n\n  function message(o, url) {\n    var first = (o.agent.split(/\\s+/)[0] || \"\").trim();\n    var extras = o.sig ? (o.plans && o.tour ? \" The floor plans and 3D tour are on the same page.\" : o.plans ? \" The floor plans are on the same page.\" : o.tour ? \" The 3D tour is on the same page.\" : \"\") : \"\";\n    return (first ? \"Hi \" + first + \", y\" : \"Y\") + \"our photos for \" + o.address + \" are ready:\\n\" + url + \"\\n\\n\" +\n      \"Tap Download All to save every photo at once.\" + extras +\n      (o.pw ? \"\\nPassword: \" + o.pw : \"\") + \"\\n\\nThanks for having me out!\\nHadi, Altus Aerials\";\n  }\n  function showResult(res, o) {\n    var r = $(\"result\"), text = message(o, res.url), digits = o.phone.replace(/\\D/g, \"\");\n    var fp = res.flightpath && res.flightpath.ok ? '<p class=\"note good\">Marked Delivered in Flightpath.</p>' :\n      '<p class=\"note\">Flightpath isn\\'t connected yet, so mark this shoot Delivered there by hand.</p>';\n    r.innerHTML = '<div class=\"card-head\"><h2>Gallery is live</h2><a class=\"btn btn-outline\" href=\"' + esc(res.url) + '\" target=\"_blank\" rel=\"noopener\">Open gallery</a></div>' +\n      '<p class=\"done-link\"><a href=\"' + esc(res.url) + '\" target=\"_blank\" rel=\"noopener\">' + esc(res.url) + '</a></p>' + fp +\n      '<label class=\"f wide\">Text for the agent (edit if you like)<textarea id=\"msg\">' + esc(text) + '</textarea></label>' +\n      '<div class=\"row\"><button class=\"btn btn-primary\" type=\"button\" id=\"copy-msg\">Copy text</button>' +\n      (digits ? '<a class=\"btn btn-outline\" id=\"sms-link\" href=\"sms:' + digits + '?&body=' + encodeURIComponent(text) + '\">Open in Messages</a>' : '') +\n      (res.autoSend && digits ? '<button class=\"btn btn-blue\" type=\"button\" id=\"send-now\">Send text now</button>' : '') + '</div>' +\n      '<label class=\"switch\"><input type=\"checkbox\" id=\"f-replace\"> Fix something and re-publish to this same link</label>';\n    r.hidden = false; r.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n    $(\"msg\").addEventListener(\"input\", function () { var a = $(\"sms-link\"); if (a) a.href = \"sms:\" + digits + \"?&body=\" + encodeURIComponent(this.value); });\n    $(\"copy-msg\").addEventListener(\"click\", function () {\n      var t = $(\"msg\"), b = this;\n      var ok = function () { b.textContent = \"Copied\"; setTimeout(function () { b.textContent = \"Copy text\"; }, 1800); };\n      if (navigator.clipboard) navigator.clipboard.writeText(t.value).then(ok, function () { t.select(); document.execCommand(\"copy\"); ok(); });\n      else { t.select(); document.execCommand(\"copy\"); ok(); }\n    });\n    if ($(\"send-now\")) $(\"send-now\").addEventListener(\"click\", function () {\n      var b = this; b.disabled = true;\n      S.api(\"/api/studio/send-text\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ to: digits, body: $(\"msg\").value }) })\n        .then(function (x) { b.textContent = x.sent ? \"Sent\" : \"Not sent\"; }, function () { b.textContent = \"Not sent\"; b.disabled = false; });\n    });\n  }\n})();\n"}, "/assets/studio/config.js": {"type": "text/javascript; charset=utf-8", "body": "/* Where the Altus API (Cloudflare Worker) lives.\n   (When these pages are served by the Worker itself, the Worker rewrites this file to its own address.) */\nwindow.ALTUS_API = \"https://altus-api.hadi-583.workers.dev\";\n"}, "/assets/studio/rebook.css": {"type": "text/css; charset=utf-8", "body": "/* Extras for /rebook/ on top of the site's own /assets/css/style.css (read-only, not edited). */\n[hidden] { display: none !important; }\n.rebook-hero { padding: 70px 0 40px; }\n.rebook-eyebrow { text-transform: uppercase; letter-spacing: .16em; font-size: 12px; font-weight: 600; color: var(--blue-accent); }\n.rebook-section { padding: 30px 0 100px; }\n.rebook-form, .rebook-done { max-width: 640px; margin: 0 auto; }\n.rebook-form h3 { font-size: 22px; margin: 34px 0 14px; }\n.rebook-form h3:first-of-type { margin-top: 0; }\n\n.rebook-packages { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.rebook-pkg {\n  position: relative; display: flex; flex-direction: column; gap: 2px; padding: 18px 16px; cursor: pointer;\n  border: 1px solid var(--line); border-radius: var(--radius); background: #fff;\n  transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;\n}\n.rebook-pkg:hover { transform: translateY(-2px); box-shadow: 0 12px 24px rgba(11, 37, 69, .08); }\n.rebook-pkg input { position: absolute; opacity: 0; pointer-events: none; }\n.rebook-pkg .tier-name { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); font-weight: 600; }\n.rebook-pkg .price { font-family: var(--serif); font-size: 30px; color: var(--ink); }\n.rebook-pkg .price sup { font-size: 14px; margin-right: 2px; }\n.rebook-pkg .tagline { font-size: 13px; color: var(--muted); line-height: 1.4; }\n.rebook-pkg:has(input:checked) { border-color: var(--navy); background: linear-gradient(180deg, #fff 0%, var(--paper-soft) 100%); box-shadow: 0 0 0 2px var(--navy); }\n.rebook-pkg:has(input:focus-visible) { outline: 3px solid var(--blue-accent); outline-offset: 2px; }\n\n.rebook-prefill { font-size: 14px; margin: -4px 0 14px; }\n.rebook-clear { background: none; border: 0; padding: 0; color: var(--blue-accent); font: inherit; font-weight: 600; cursor: pointer; text-decoration: underline; text-underline-offset: 3px; }\n.rebook-fine { font-size: 13px; margin-top: 12px; }\n.rebook-form .btn { width: 100%; }\n.rebook-done p { margin-bottom: 20px; }\n.form-field input, .form-field select, .form-field textarea { font-size: 16px; } /* stops iPhone zoom-on-focus */\n@media (min-width: 640px) { .rebook-form .btn { width: auto; } }\n"}, "/assets/css/style.css": {"type": "text/css; charset=utf-8", "body": "/* ============================================\n   Altus Aerials \u2014 shared styles\n   ============================================ */\n\n:root {\n  --navy: #0b2545;\n  --navy-deep: #071a33;\n  --blue-accent: #4c8dff;\n  --blue-light: #8ec5ff;\n  --ink: #101828;\n  --muted: #5b6474;\n  --paper: #ffffff;\n  --paper-soft: #f6f8fb;\n  --line: #e4e8ef;\n  --radius: 14px;\n  --max-width: 1180px;\n  --serif: \"Fraunces\", Georgia, serif;\n  --sans: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n* { box-sizing: border-box; }\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n  margin: 0;\n  font-family: var(--sans);\n  color: var(--ink);\n  background: var(--paper);\n  -webkit-font-smoothing: antialiased;\n}\n\nimg { max-width: 100%; display: block; }\n\na { color: inherit; text-decoration: none; }\n\n.wrap {\n  max-width: var(--max-width);\n  margin: 0 auto;\n  padding: 0 32px;\n}\n\nh1, h2, h3 {\n  font-family: var(--serif);\n  font-weight: 500;\n  line-height: 1.15;\n  margin: 0 0 16px;\n  letter-spacing: -0.01em;\n}\n\np { line-height: 1.7; color: var(--muted); margin: 0 0 16px; }\n\n/* ---------- Header ---------- */\n.site-header {\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  background: rgba(11, 37, 69, 0.96);\n  backdrop-filter: blur(10px);\n  border-bottom: 1px solid rgba(255, 255, 255, 0.12);\n  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.12);\n  transition: background 0.35s ease, backdrop-filter 0.35s ease, border-color 0.35s ease;\n}\n\n.site-header .wrap {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: 76px;\n  gap: 20px;\n}\n\n.nav-links {\n  display: flex;\n  gap: 32px;\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.nav-links a {\n  font-size: 14px;\n  font-weight: 500;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n  color: rgba(255, 255, 255, 0.82);\n  padding-bottom: 4px;\n  border-bottom: 2px solid transparent;\n  transition: border-color 0.2s ease, color 0.2s ease;\n}\n\n.nav-links a:hover,\n.nav-links a.active {\n  color: #fff;\n  border-color: var(--blue-accent);\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-family: var(--serif);\n  font-size: 20px;\n  letter-spacing: 0.02em;\n  color: #fff;\n  transition: color 0.35s ease;\n}\n\n.brand img { height: 32px; width: auto; }\n\n.header-right { display: flex; align-items: center; gap: 20px; }\n\n.socials {\n  display: flex;\n  gap: 18px;\n}\n\n.socials a {\n  width: 34px;\n  height: 34px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  border: 1px solid rgba(255, 255, 255, 0.35);\n  color: #fff;\n  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;\n}\n\n.socials a:hover { background: #fff; border-color: #fff; color: var(--navy); }\n.socials svg { width: 16px; height: 16px; }\n\n.nav-cta {\n  padding: 10px 22px;\n  font-size: 12px;\n  background: #fff;\n  color: var(--navy);\n  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.2);\n}\n.nav-cta:hover { transform: translateY(-2px); box-shadow: 0 10px 20px rgba(0, 0, 0, 0.28); }\n\n.nav-toggle { display: none; }\n\n/* Transparent header over the home hero video \u2014 solid navy state kicks in on scroll (see main.js) */\n.site-header.header-transparent {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  background: transparent;\n  backdrop-filter: none;\n  border-bottom-color: transparent;\n  box-shadow: none;\n}\n\n.site-header.header-transparent.is-scrolled {\n  background: rgba(11, 37, 69, 0.96);\n  backdrop-filter: blur(10px);\n  border-bottom-color: rgba(255, 255, 255, 0.12);\n  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.12);\n}\n\n/* ---------- Buttons ---------- */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 14px 30px;\n  border-radius: 999px;\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: 0.03em;\n  text-transform: uppercase;\n  cursor: pointer;\n  border: 1px solid transparent;\n  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;\n}\n\n.btn-primary {\n  background: var(--navy);\n  color: #fff;\n  box-shadow: 0 8px 24px rgba(11, 37, 69, 0.25);\n}\n\n.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 12px 28px rgba(11, 37, 69, 0.32); }\n\n.btn-outline {\n  background: transparent;\n  border-color: var(--line);\n  color: var(--ink);\n}\n\n.btn-outline:hover { border-color: var(--navy); }\n\n.btn-light {\n  background: #fff;\n  color: var(--navy);\n}\n.btn-light:hover { transform: translateY(-2px); }\n\n/* ---------- Hero ---------- */\n.hero {\n  position: relative;\n  min-height: 86vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  color: #fff;\n  background: linear-gradient(180deg, var(--navy-deep) 0%, var(--navy) 100%);\n  overflow: hidden;\n}\n\n.hero::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  background: radial-gradient(circle at 50% 20%, rgba(76, 141, 255, 0.25), transparent 60%);\n  pointer-events: none;\n}\n\n.hero-inner { position: relative; z-index: 1; max-width: 760px; padding: 0 24px; }\n\n.hero .eyebrow {\n  text-transform: uppercase;\n  letter-spacing: 0.2em;\n  font-size: 12px;\n  color: var(--blue-light);\n  margin-bottom: 18px;\n  display: block;\n}\n\n.hero h1 {\n  font-size: clamp(40px, 6vw, 68px);\n  color: #fff;\n  margin-bottom: 20px;\n}\n\n.hero p {\n  font-size: 18px;\n  color: rgba(255, 255, 255, 0.78);\n  max-width: 560px;\n  margin: 0 auto 32px;\n}\n\n/* ---------- Video hero (home page) ---------- */\n.hero-video-section {\n  position: relative;\n  height: 100svh;\n  min-height: 560px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  color: #fff;\n  overflow: hidden;\n  background: var(--navy-deep);\n}\n\n.hero-video {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  z-index: 0;\n  will-change: transform;\n  transform: scale(1.08);\n}\n\n.hero-video-overlay {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  background: linear-gradient(180deg, rgba(7, 26, 51, 0.55) 0%, rgba(7, 26, 51, 0.35) 45%, rgba(7, 26, 51, 0.6) 100%);\n  pointer-events: none;\n}\n\n.hero-video-section .hero-inner { position: relative; z-index: 2; }\n.hero-video-section .hero-inner p { color: rgba(255, 255, 255, 0.92); }\n\n.hero-scroll-cue {\n  position: absolute;\n  bottom: 28px;\n  left: 50%;\n  transform: translateX(-50%);\n  z-index: 2;\n  width: 22px;\n  height: 36px;\n  border: 2px solid rgba(255, 255, 255, 0.6);\n  border-radius: 999px;\n}\n.hero-scroll-cue::before {\n  content: \"\";\n  position: absolute;\n  top: 6px;\n  left: 50%;\n  width: 4px;\n  height: 8px;\n  background: #fff;\n  border-radius: 999px;\n  transform: translateX(-50%);\n  animation: scroll-cue 1.8s ease-in-out infinite;\n}\n@keyframes scroll-cue {\n  0% { opacity: 1; transform: translate(-50%, 0); }\n  70% { opacity: 0; transform: translate(-50%, 14px); }\n  100% { opacity: 0; transform: translate(-50%, 14px); }\n}\n\n/* ---------- Sections ---------- */\nsection { padding: 100px 0; }\n.section-soft { background: var(--paper-soft); }\n\n.section-head { text-align: center; max-width: 640px; margin: 0 auto 56px; }\n.section-head .eyebrow {\n  text-transform: uppercase;\n  letter-spacing: 0.16em;\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--blue-accent);\n  margin-bottom: 12px;\n  display: block;\n}\n.section-head h2 { font-size: clamp(28px, 4vw, 40px); }\n\n/* ---------- Service teaser cards ---------- */\n.grid-2 {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 28px;\n}\n\n.teaser-card {\n  border-radius: var(--radius);\n  padding: 44px 36px;\n  background: #fff;\n  border: 1px solid var(--line);\n  transition: transform 0.25s ease, box-shadow 0.25s ease;\n}\n\n.teaser-card:hover { transform: translateY(-6px); box-shadow: 0 20px 40px rgba(11, 37, 69, 0.1); }\n\n.teaser-card .icon {\n  width: 52px; height: 52px;\n  border-radius: 12px;\n  background: linear-gradient(135deg, var(--navy), var(--blue-accent));\n  margin-bottom: 22px;\n  display: flex; align-items: center; justify-content: center;\n}\n.teaser-card .icon svg { width: 24px; height: 24px; stroke: #fff; }\n\n.teaser-card h3 { font-size: 22px; margin-bottom: 10px; }\n\n.teaser-card .learn-more {\n  font-size: 13px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--navy);\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  margin-top: 6px;\n}\n.teaser-card .learn-more svg { width: 14px; height: 14px; transition: transform 0.2s ease; }\n.teaser-card:hover .learn-more svg { transform: translateX(4px); }\n\n/* ---------- CTA banner ---------- */\n.cta-banner {\n  background: var(--navy);\n  color: #fff;\n  text-align: center;\n  padding: 90px 0;\n}\n.cta-banner h2 { color: #fff; font-size: clamp(26px, 4vw, 38px); margin-bottom: 8px;}\n.cta-banner p { color: rgba(255,255,255,0.7); margin-bottom: 30px; }\n\n/* ---------- Pricing cards ---------- */\n.pricing-group { margin-bottom: 90px; }\n.pricing-group:last-child { margin-bottom: 0; }\n\n.pricing-group-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 20px;\n  margin-bottom: 36px;\n  border-bottom: 1px solid var(--line);\n  padding-bottom: 24px;\n}\n.pricing-group-head h2 { margin-bottom: 6px; }\n\n.pricing-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 24px;\n}\n\n.price-card {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 32px 26px;\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  background: #fff;\n  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;\n}\n.price-card:hover { transform: translateY(-4px); box-shadow: 0 16px 32px rgba(11,37,69,0.08); }\n\n.price-card.featured {\n  border-color: var(--navy);\n  background: linear-gradient(180deg, #ffffff 0%, var(--paper-soft) 100%);\n}\n\n.price-card .badge {\n  position: absolute;\n  top: -12px; left: 26px;\n  background: var(--navy);\n  color: #fff;\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  padding: 5px 12px;\n  border-radius: 999px;\n  font-weight: 600;\n}\n\n.price-card .tier-name { font-size: 13px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); font-weight: 600; margin-bottom: 10px; }\n.price-card .price { font-family: var(--serif); font-size: 40px; margin-bottom: 14px; }\n.price-card .price sup { font-size: 16px; margin-right: 2px; }\n.price-card .tagline { font-size: 14px; margin-bottom: 20px; min-height: 42px; }\n\n.price-card ul { list-style: none; margin: 0 0 26px; padding: 0; flex: 1; }\n.price-card li {\n  font-size: 14px;\n  color: var(--ink);\n  padding: 9px 0;\n  border-top: 1px solid var(--line);\n  display: flex;\n  gap: 10px;\n}\n.price-card li:first-child { border-top: none; }\n.price-card li svg { width: 16px; height: 16px; flex-shrink: 0; margin-top: 2px; stroke: var(--blue-accent); }\n\n.retainer-note {\n  margin-top: 18px;\n  font-size: 13px;\n  text-align: center;\n  color: var(--muted);\n}\n\n/* ---------- About ---------- */\n.about-hero {\n  background: linear-gradient(135deg, var(--navy) 0%, #163a63 60%, var(--blue-accent) 160%);\n  color: #fff;\n  padding: 130px 0 90px;\n}\n.about-hero h1 { color: #fff; font-size: clamp(32px, 5vw, 52px); max-width: 900px; }\n\n.about-body {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 60px;\n  align-items: center;\n  padding: 100px 0;\n}\n.about-body img { border-radius: var(--radius); }\n.about-body .stat-row { display: flex; gap: 32px; margin-top: 32px; }\n.about-body .stat { }\n.about-body .stat strong { font-family: var(--serif); font-size: 28px; display: block; color: var(--navy); }\n.about-body .stat span { font-size: 13px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.04em; }\n\n/* ---------- Contact ---------- */\n.contact-hero {\n  background: var(--paper-soft);\n  padding: 120px 0 60px;\n  text-align: center;\n}\n.contact-hero h1 { font-size: clamp(32px, 5vw, 50px); }\n.contact-hero p { max-width: 480px; margin: 0 auto; }\n\n.contact-layout {\n  display: grid;\n  grid-template-columns: 1.3fr 0.7fr;\n  gap: 48px;\n  padding: 70px 0 110px;\n  align-items: start;\n}\n\n.booking-panel-copy { color: var(--muted); font-size: 15px; margin-bottom: 20px; max-width: 480px; }\n\n/* ---------- Booking forms ---------- */\n.booking-form { max-width: 560px; }\n.hp-field { position: absolute; left: -9999px; }\n\n.form-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 18px;\n}\n\n.form-field { margin-bottom: 18px; }\n.form-field label {\n  display: block;\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  font-weight: 600;\n  color: var(--muted);\n  margin-bottom: 7px;\n}\n\n.form-field input,\n.form-field select,\n.form-field textarea {\n  width: 100%;\n  padding: 12px 14px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  font-family: inherit;\n  font-size: 15px;\n  color: var(--ink);\n  background: #fff;\n  transition: border-color 0.2s ease, box-shadow 0.2s ease;\n}\n\n.form-field input:focus,\n.form-field select:focus,\n.form-field textarea:focus {\n  outline: none;\n  border-color: var(--blue-accent);\n  box-shadow: 0 0 0 3px rgba(76, 141, 255, 0.15);\n}\n\n.form-field textarea { resize: vertical; min-height: 80px; }\n\n.slot-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.slot-hint, .slot-empty { color: var(--muted); font-size: 14px; margin: 0; }\n.slot-button {\n  padding: 10px 16px;\n  border-radius: 999px;\n  border: 1px solid var(--line);\n  background: #fff;\n  color: var(--ink);\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease;\n}\n.slot-button:hover { border-color: var(--navy); }\n.slot-button.is-selected {\n  background: var(--navy);\n  border-color: var(--navy);\n  color: #fff;\n}\n.slot-button:disabled { opacity: 0.4; cursor: not-allowed; }\n\n.form-error {\n  color: #b3261e;\n  font-size: 14px;\n  margin: -6px 0 18px;\n}\n\n.checkbox-group { display: flex; gap: 18px; flex-wrap: wrap; }\n.checkbox-option {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  font-size: 14px;\n  color: var(--ink);\n  text-transform: none;\n  letter-spacing: normal;\n  font-weight: 500;\n  cursor: pointer;\n}\n.checkbox-option input { width: auto; }\n\n.booking-form .btn { margin-top: 6px; }\n\n@media (max-width: 640px) {\n  .form-row { grid-template-columns: 1fr; gap: 0; }\n}\n\n.contact-card {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 36px;\n  background: #fff;\n}\n.contact-card h3 { font-size: 22px; margin-bottom: 24px; }\n.contact-item { margin-bottom: 24px; }\n.contact-item:last-child { margin-bottom: 0; }\n.contact-item .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); font-weight: 600; margin-bottom: 6px; }\n.contact-item a, .contact-item span { font-size: 15px; color: var(--ink); display: block; }\n.contact-item a:hover { color: var(--blue-accent); }\n\n/* ---------- Footer ---------- */\nfooter {\n  background: var(--navy-deep);\n  color: rgba(255,255,255,0.7);\n  padding: 60px 0 30px;\n}\nfooter .footer-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 24px;\n  padding-bottom: 36px;\n  border-bottom: 1px solid rgba(255,255,255,0.1);\n  margin-bottom: 24px;\n}\nfooter .brand { color: #fff; }\nfooter nav { display: flex; gap: 24px; flex-wrap: wrap; }\nfooter nav a { font-size: 13px; text-transform: uppercase; letter-spacing: 0.04em; color: rgba(255,255,255,0.7); }\nfooter nav a:hover { color: #fff; }\nfooter .footer-bottom {\n  display: flex;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 12px;\n  font-size: 13px;\n  color: rgba(255,255,255,0.45);\n}\nfooter .socials a { border-color: rgba(255,255,255,0.2); color: #fff; }\n\n/* Header is always navy or transparent-over-dark now, so the header logo\n   is always the white/light mark \u2014 no swap needed. */\n\n/* ---------- About contact strip ---------- */\n.about-contact {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 28px 32px;\n  margin-top: 40px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 28px;\n  align-items: center;\n  background: var(--paper-soft);\n}\n.about-contact .about-contact-item .label {\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--muted);\n  font-weight: 600;\n  margin-bottom: 4px;\n}\n.about-contact .about-contact-item a,\n.about-contact .about-contact-item span { display: block; font-size: 15px; color: var(--ink); }\n.about-contact .about-contact-item a:hover { color: var(--blue-accent); }\n\n/* ---------- Scroll reveal ---------- */\n.reveal {\n  opacity: 0;\n  transform: translateY(20px);\n  transition: opacity 0.7s cubic-bezier(0.22, 0.61, 0.36, 1), transform 0.7s cubic-bezier(0.22, 0.61, 0.36, 1);\n  will-change: opacity, transform;\n}\n.reveal.in-view {\n  opacity: 1;\n  transform: translateY(0);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  .reveal { opacity: 1; transform: none; transition: none; }\n  .hero-scroll-cue::before { animation: none; }\n  .hero-video { transform: none !important; }\n}\n\n/* ---------- Utility ---------- */\n.center { text-align: center; }\n.mt-40 { margin-top: 40px; }\n\n/* ---------- Portfolio grid ---------- */\n.portfolio-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 20px;\n}\n.portfolio-grid img {\n  width: 100%;\n  aspect-ratio: 4 / 3;\n  object-fit: cover;\n  border-radius: var(--radius);\n  display: block;\n}\n\n/* ---------- Responsive ---------- */\n@media (max-width: 860px) {\n  .grid-2, .about-body, .contact-layout { grid-template-columns: 1fr; }\n  .portfolio-grid { grid-template-columns: repeat(2, 1fr); }\n  .about-body { padding: 70px 0; }\n  .nav-links { display: none; }\n  section { padding: 70px 0; }\n  .nav-cta { padding: 9px 16px; font-size: 11px; }\n  .about-contact { padding: 24px; gap: 20px; }\n}\n\n@media (max-width: 560px) {\n  .site-header .socials { display: none; }\n  .brand span.brand-text { display: none; }\n}\n"}, "/studio/upload/index.html": {"type": "text/html; charset=utf-8", "body": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Deliver a Shoot | Altus Studio</title>\n<link rel=\"icon\" href=\"/assets/images/favicon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Inter:wght@400;500;600;700&display=swap\">\n<link rel=\"stylesheet\" href=\"/assets/studio/studio.css\">\n</head>\n<body>\n<header class=\"bar\"><div class=\"in\">\n  <a class=\"brand\" href=\"/studio/upload/\"><img src=\"/assets/images/logo-white.png\" alt=\"Altus Aerials logo\"> <span class=\"brand-text\">Altus Aerials</span><span class=\"studio-tag\">Studio</span></a>\n  <nav><a href=\"/studio/upload/\" aria-current=\"page\">Deliver</a><a href=\"/studio/activity/\">Activity</a></nav>\n</div></header>\n<main class=\"page\" id=\"app\"><p class=\"muted\">Loading\u2026</p></main>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js\"></script>\n<script src=\"/assets/studio/config.js\"></script>\n<script src=\"/assets/studio/studio.js\"></script>\n<script src=\"/assets/studio/upload.js\"></script>\n</body>\n</html>\n"}, "/studio/activity/index.html": {"type": "text/html; charset=utf-8", "body": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Gallery Activity | Altus Studio</title>\n<link rel=\"icon\" href=\"/assets/images/favicon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Inter:wght@400;500;600;700&display=swap\">\n<link rel=\"stylesheet\" href=\"/assets/studio/studio.css\">\n</head>\n<body>\n<header class=\"bar\"><div class=\"in\">\n  <a class=\"brand\" href=\"/studio/upload/\"><img src=\"/assets/images/logo-white.png\" alt=\"Altus Aerials logo\"> <span class=\"brand-text\">Altus Aerials</span><span class=\"studio-tag\">Studio</span></a>\n  <nav><a href=\"/studio/upload/\">Deliver</a><a href=\"/studio/activity/\" aria-current=\"page\">Activity</a></nav>\n</div></header>\n<main class=\"page\" id=\"app\"><p class=\"muted\">Loading\u2026</p></main>\n<script src=\"/assets/studio/config.js\"></script>\n<script src=\"/assets/studio/studio.js\"></script>\n<script>\n(function () {\n  \"use strict\";\n  var S = window.Studio, esc = S.esc, app = document.getElementById(\"app\"), data = null, tab = \"galleries\";\n  var DAY = 864e5;\n  function fmtDate(ms) { return ms ? new Date(ms).toLocaleDateString(\"en-US\", { month: \"short\", day: \"numeric\" }) : \"\u2014\"; }\n  function ago(ms) {\n    if (!ms) return \"\u2014\"; var m = Math.round((Date.now() - ms) / 6e4);\n    return m < 60 ? m + \" min ago\" : m < 1440 ? Math.round(m / 60) + \" hr ago\" : Math.round(m / 1440) + \" days ago\";\n  }\n  function daysSince(iso) { if (!iso) return null; return Math.floor((Date.now() - new Date(iso + \"T12:00:00\").getTime()) / DAY); }\n  function n(v) { return v ? v : '<span class=\"muted\">0</span>'; }\n\n  S.requireKey(app, load);\n  function load() {\n    S.api(\"/api/studio/activity\").then(function (d) { data = d; render(); }, function (e) { app.innerHTML = '<p class=\"note bad\">' + esc(e.message) + '</p>'; });\n  }\n  function render() {\n    var g = data.galleries, unopened = g.filter(function (x) { return !x.opens && Date.now() - x.created_at > DAY; });\n    var opened7 = g.filter(function (x) { return x.last_seen && Date.now() - x.last_seen < 7 * DAY; }).length;\n    var req = data.bookings.filter(function (b) { return b.status === \"requested\"; }).length;\n    var due = data.agents.filter(function (a) { var d = daysSince(a.last); return d != null && d >= 30; }).length;\n    app.innerHTML =\n      '<div class=\"card-head\"><div><h1>Activity</h1><p class=\"lede\">Who opened their gallery, what they downloaded, and which agents are due for a call.</p></div>' +\n      '<button class=\"btn btn-outline\" type=\"button\" id=\"refresh\">Refresh</button></div>' +\n      '<div class=\"stats\">' +\n        stat(g.length, \"galleries delivered\") + stat(opened7, \"opened in the last 7 days\") +\n        stat(unopened.length, \"not opened after a day\") + stat(req, \"booking requests waiting\") + stat(due, \"agents 30+ days since last shoot\") +\n      '</div>' +\n      '<div class=\"tabs\" role=\"tablist\">' + tabBtn(\"galleries\", \"Galleries\") + tabBtn(\"agents\", \"Agents\") + tabBtn(\"bookings\", \"Booking requests\" + (req ? \" (\" + req + \")\" : \"\")) + '</div>' +\n      '<div id=\"panel\"></div>' +\n      (data.source !== \"flightpath\" ? '<p class=\"muted\">Last-shoot dates come from delivered galleries and booking requests until Flightpath is connected.</p>' : '');\n    document.getElementById(\"refresh\").onclick = load;\n    app.querySelectorAll(\"[role=tab]\").forEach(function (b) { b.onclick = function () { tab = b.dataset.tab; render(); }; });\n    var p = document.getElementById(\"panel\");\n    p.innerHTML = tab === \"galleries\" ? galleries() : tab === \"agents\" ? agents() : bookings();\n  }\n  function stat(v, label) { return '<div class=\"stat\"><b>' + v + '</b><span>' + label + '</span></div>'; }\n  function tabBtn(id, label) { return '<button type=\"button\" role=\"tab\" data-tab=\"' + id + '\" aria-selected=\"' + (tab === id) + '\">' + label + '</button>'; }\n\n  function galleries() {\n    if (!data.galleries.length) return '<div class=\"card\"><p style=\"margin:0\">No galleries yet. Deliver your first shoot from the Deliver tab.</p></div>';\n    return '<div class=\"tablewrap\"><table><thead><tr><th>Gallery</th><th>Status</th><th class=\"num\">Opens</th><th>Last seen</th><th class=\"num\">Zip</th><th class=\"num\">Saves</th><th class=\"num\">Tour</th><th class=\"num\">Shares</th><th class=\"num\">Book clicks</th></tr></thead><tbody>' +\n      data.galleries.map(function (x) {\n        var status = !x.opens ? (Date.now() - x.created_at > DAY ? '<span class=\"pill bad\">Not opened</span>' : '<span class=\"pill\">Sent</span>') :\n          x.zips ? '<span class=\"pill good\">Downloaded</span>' : '<span class=\"pill warn\">Opened</span>';\n        return '<tr><td><a href=\"/gallery/' + esc(x.slug) + '/\" target=\"_blank\" rel=\"noopener\"><b>' + esc(x.address) + '</b></a>' + (x.locked ? ' <span class=\"pill\">Locked</span>' : '') +\n          '<span class=\"sub\">' + esc([x.package, x.agent_name, \"delivered \" + fmtDate(x.created_at)].filter(Boolean).join(\" \u00b7 \")) + '</span></td>' +\n          '<td>' + status + '</td><td class=\"num\">' + n(x.opens) + (x.visitors > 1 ? '<span class=\"sub\">' + x.visitors + ' people</span>' : '') + '</td>' +\n          '<td>' + ago(x.last_seen) + '</td><td class=\"num\">' + n(x.zips) + '</td><td class=\"num\">' + n(x.saves) + '</td><td class=\"num\">' + n(x.tour) + '</td><td class=\"num\">' + n(x.shares) + '</td><td class=\"num\">' + n(x.book_clicks) + '</td></tr>';\n      }).join(\"\") + '</tbody></table></div>';\n  }\n  function agents() {\n    var list = data.agents.slice().sort(function (a, b) { return (daysSince(b.last) || 0) - (daysSince(a.last) || 0); });\n    if (!list.length) return '<div class=\"card\"><p style=\"margin:0\">Agents show up here once a gallery is delivered with their mobile number.</p></div>';\n    return '<div class=\"tablewrap\"><table><thead><tr><th>Agent</th><th>Mobile</th><th>Last / next shoot</th><th class=\"num\">Days since</th><th class=\"num\">Galleries</th></tr></thead><tbody>' +\n      list.map(function (a) {\n        var d = daysSince(a.last), pill = d == null ? \"\u2014\" : d < 0 ? '<span class=\"pill good\">Booked</span>' : d >= 60 ? '<span class=\"pill bad\">' + d + '</span>' : d >= 30 ? '<span class=\"pill warn\">' + d + '</span>' : '<span class=\"pill good\">' + d + '</span>';\n        return '<tr><td><b>' + esc(a.name || \"Unknown\") + '</b></td><td>' + esc(a.phone) + '</td><td>' + esc(a.last || \"\u2014\") + '</td><td class=\"num\">' + pill + '</td><td class=\"num\">' + a.shoots + '</td></tr>';\n      }).join(\"\") + '</tbody></table></div>';\n  }\n  function bookings() {\n    if (!data.bookings.length) return '<div class=\"card\"><p style=\"margin:0\">No booking requests yet. They come from the \"Book your next shoot\" button on every gallery.</p></div>';\n    return '<div class=\"tablewrap\"><table><thead><tr><th>Requested</th><th>Who</th><th>Property</th><th>Package</th><th>Wants</th><th>Notes</th></tr></thead><tbody>' +\n      data.bookings.map(function (b) {\n        return '<tr><td>' + fmtDate(b.created_at) + '<span class=\"sub\">' + (b.flightpath_id ? \"In Flightpath\" : \"Not in Flightpath yet\") + '</span></td>' +\n          '<td><b>' + esc(b.name) + '</b><span class=\"sub\">' + esc(b.phone) + (b.email ? \" \u00b7 \" + esc(b.email) : \"\") + '</span></td>' +\n          '<td>' + esc(b.address) + '<span class=\"sub\">' + esc(b.city || \"\") + (b.from_slug ? \" \u00b7 from \" + esc(b.from_slug) : \"\") + '</span></td>' +\n          '<td>' + esc(b.package) + '</td><td>' + esc(b.date) + '<span class=\"sub\">' + esc(b.time_window || \"\") + '</span></td>' +\n          '<td style=\"white-space:normal;min-width:180px\">' + esc(b.notes || \"\") + '</td></tr>';\n      }).join(\"\") + '</tbody></table></div>';\n  }\n})();\n</script>\n</body>\n</html>\n"}, "/rebook/index.html": {"type": "text/html; charset=utf-8", "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n<title>Book Your Next Shoot | Altus Aerials</title>\n<meta name=\"description\" content=\"Request your next real estate shoot with Altus Aerials. No account needed.\">\n<meta name=\"robots\" content=\"noindex\">\n<link rel=\"icon\" href=\"/assets/images/favicon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"/assets/css/style.css\">\n<link rel=\"stylesheet\" href=\"/assets/studio/rebook.css\">\n</head>\n<body>\n\n<header class=\"site-header\">\n  <div class=\"wrap\">\n    <nav class=\"nav-links\">\n      <a href=\"/\">Home</a>\n      <a href=\"/services.html\">Services</a>\n      <a href=\"/about.html\">About</a>\n    </nav>\n    <a href=\"/\" class=\"brand\"><img src=\"/assets/images/logo-white.png\" alt=\"Altus Aerials logo\"> <span class=\"brand-text\">Altus Aerials</span></a>\n    <div class=\"header-right\">\n      <div class=\"socials\">\n        <a href=\"https://www.instagram.com/altusaerials/\" aria-label=\"Instagram\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"/></svg></a>\n        <a href=\"https://www.tiktok.com/@altusaerials\" aria-label=\"TikTok\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M16.5 2h-3v14.2a2.8 2.8 0 1 1-2-2.68V10.4a6 6 0 1 0 5 5.92V9.3a7.5 7.5 0 0 0 4.5 1.5V7.6A4.5 4.5 0 0 1 16.5 2z\"/></svg></a>\n        <a href=\"https://www.facebook.com/profile.php?id=61591853282817\" aria-label=\"Facebook\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M13.5 21v-8h2.7l.4-3.2h-3.1V7.7c0-.9.3-1.6 1.6-1.6h1.7V3.2C16.5 3.1 15.5 3 14.4 3c-2.4 0-4 1.5-4 4.1v2.7H7.7V13h2.7v8h3.1z\"/></svg></a>\n      </div>\n    </div>\n  </div>\n</header>\n\n<section class=\"contact-hero rebook-hero\">\n  <div class=\"wrap\">\n    <span class=\"rebook-eyebrow\">Book Again</span>\n    <h1>Book Your Next Shoot</h1>\n    <p>Pick a package and a day. No account needed. Hadi confirms by text, usually the same day.</p>\n  </div>\n</section>\n\n<section class=\"rebook-section\">\n  <div class=\"wrap\">\n    <form name=\"rebook\" method=\"POST\" data-netlify=\"true\" netlify-honeypot=\"bot-field\" class=\"booking-form rebook-form\" id=\"rebook\" novalidate>\n      <input type=\"hidden\" name=\"form-name\" value=\"rebook\">\n      <input type=\"hidden\" name=\"from\" id=\"from\">\n      <input type=\"hidden\" name=\"window\" id=\"window\">\n      <p class=\"hp-field\" hidden><label>Don't fill this out if you're human: <input name=\"bot-field\" id=\"bot-field\"></label></p>\n\n      <h3>Step 1: Pick Your Package</h3>\n      <div class=\"rebook-packages\" role=\"radiogroup\" aria-label=\"Package\">\n        <label class=\"rebook-pkg\"><input type=\"radio\" name=\"package\" value=\"Overview\"><span class=\"tier-name\">Overview</span><span class=\"price\"><sup>$</sup>149</span><span class=\"tagline\">Exterior aerial photos</span></label>\n        <label class=\"rebook-pkg\"><input type=\"radio\" name=\"package\" value=\"Showcase\"><span class=\"tier-name\">Showcase</span><span class=\"price\"><sup>$</sup>349</span><span class=\"tagline\">Aerial photos + video, full interiors</span></label>\n        <label class=\"rebook-pkg\"><input type=\"radio\" name=\"package\" value=\"Signature\"><span class=\"tier-name\">Signature</span><span class=\"price\"><sup>$</sup>499</span><span class=\"tagline\">Showcase + 3D tour + floor plans</span></label>\n        <label class=\"rebook-pkg\"><input type=\"radio\" name=\"package\" value=\"Summit\"><span class=\"tier-name\">Summit</span><span class=\"price\"><sup>$</sup>649</span><span class=\"tagline\">Signature + cinematic FPV fly-through</span></label>\n      </div>\n\n      <h3>Step 2: Pick a Day</h3>\n      <div class=\"form-field\">\n        <label for=\"date\">Date</label>\n        <input type=\"date\" id=\"date\" name=\"date\" required>\n      </div>\n      <div class=\"form-field\">\n        <label id=\"time-label\">Time</label>\n        <div id=\"slots\" class=\"slot-grid\" aria-labelledby=\"time-label\" aria-live=\"polite\">\n          <p class=\"slot-hint\">Pick a date above to see times.</p>\n        </div>\n      </div>\n\n      <h3>Step 3: The Property</h3>\n      <div class=\"form-field\">\n        <label for=\"address\">Property Address</label>\n        <input type=\"text\" id=\"address\" name=\"address\" autocomplete=\"street-address\" required>\n      </div>\n      <div class=\"form-field\">\n        <label for=\"city\">City</label>\n        <input type=\"text\" id=\"city\" name=\"city\" autocomplete=\"address-level2\">\n      </div>\n\n      <h3>Step 4: Your Details</h3>\n      <p class=\"rebook-prefill\" id=\"prefill-note\" hidden>Filled in from your last shoot. <button type=\"button\" class=\"rebook-clear\" id=\"clear-me\">Not you? Clear</button></p>\n      <div class=\"form-row\">\n        <div class=\"form-field\">\n          <label for=\"name\">Name</label>\n          <input type=\"text\" id=\"name\" name=\"name\" autocomplete=\"name\" required>\n        </div>\n        <div class=\"form-field\">\n          <label for=\"phone\">Mobile</label>\n          <input type=\"tel\" id=\"phone\" name=\"phone\" autocomplete=\"tel\" required>\n        </div>\n      </div>\n      <div class=\"form-field\">\n        <label for=\"email\">Email (optional)</label>\n        <input type=\"email\" id=\"email\" name=\"email\" autocomplete=\"email\">\n      </div>\n      <div class=\"form-field\">\n        <label for=\"notes\">Anything Hadi Should Know? (optional)</label>\n        <textarea id=\"notes\" name=\"notes\" rows=\"3\" placeholder=\"Lockbox code, vacant or occupied, listing date...\"></textarea>\n      </div>\n\n      <p class=\"form-error\" id=\"err\" hidden role=\"alert\"></p>\n      <button class=\"btn btn-primary\" type=\"submit\" id=\"go\">Request Shoot</button>\n      <p class=\"rebook-fine\">This is a request, not a booking. Nothing is charged online.</p>\n    </form>\n\n    <div class=\"contact-card rebook-done\" id=\"done\" hidden aria-live=\"polite\">\n      <h3>Got it. Thanks!</h3>\n      <p>Hadi will text you to confirm the time. Questions before then? Call or text <strong>(708) 778-0566</strong>.</p>\n      <a class=\"btn btn-outline\" href=\"/\">Back to Altus Aerials</a>\n    </div>\n  </div>\n</section>\n\n<footer>\n  <div class=\"wrap\">\n    <div class=\"footer-top\">\n      <a href=\"/\" class=\"brand\"><img src=\"/assets/images/logo-white.png\" alt=\"Altus Aerials logo\"> Altus Aerials</a>\n      <nav>\n        <a href=\"/\">Home</a>\n        <a href=\"/services.html\">Services</a>\n        <a href=\"/about.html\">About</a>\n        <a href=\"/book.html\">Contact</a>\n        <a href=\"/consultation.html\">Consultation</a>\n      </nav>\n    </div>\n    <div class=\"footer-bottom\">\n      <span>&copy; 2026 Altus Aerials. All rights reserved.</span>\n      <span>hadi@altusaerials.com &middot; (708) 778-0566</span>\n    </div>\n  </div>\n</footer>\n\n<script src=\"/assets/studio/config.js\"></script>\n<script>\n(function () {\n  \"use strict\";\n  var API = (window.ALTUS_API || location.origin).replace(/\\/$/, \"\");\n  var $ = function (id) { return document.getElementById(id); };\n  var form = $(\"rebook\"), slug = new URLSearchParams(location.search).get(\"g\") || \"\";\n  var WINDOWS = [\"Morning\", \"Afternoon\", \"Twilight\", \"Flexible\"];\n  $(\"from\").value = slug;\n  var t = new Date(); t.setDate(t.getDate() + 1);\n  $(\"date\").min = t.getFullYear() + \"-\" + String(t.getMonth() + 1).padStart(2, \"0\") + \"-\" + String(t.getDate()).padStart(2, \"0\");\n\n  // Pre-fill from the gallery the visitor came from. Sellers open forwarded galleries too,\n  // so every field stays editable and \"Not you? Clear\" wipes them.\n  if (slug) fetch(API + \"/api/rebook/prefill?g=\" + encodeURIComponent(slug)).then(function (r) { return r.json(); }).then(function (p) {\n    if (!p) return;\n    var filled = false;\n    [[\"name\", p.name], [\"phone\", p.phone], [\"email\", p.email]].forEach(function (x) { if (x[1] && !$(x[0]).value) { $(x[0]).value = x[1]; filled = true; } });\n    if (filled) $(\"prefill-note\").hidden = false;\n    if (p.lastPackage) { var r = form.querySelector('input[name=package][value=\"' + p.lastPackage + '\"]'); if (r && !form.querySelector(\"input[name=package]:checked\")) r.checked = true; }\n  }).catch(function () {});\n  $(\"clear-me\").addEventListener(\"click\", function () {\n    [\"name\", \"phone\", \"email\"].forEach(function (id) { $(id).value = \"\"; });\n    $(\"prefill-note\").hidden = true; $(\"name\").focus();\n  });\n\n  // Times: use the site's live availability (same as /book.html) when it answers;\n  // otherwise offer time-of-day choices. Either way it's a request Hadi confirms.\n  function fmt(hhmm) { var p = hhmm.split(\":\"), h = +p[0], h12 = h % 12 || 12; return h12 + \":\" + p[1] + \" \" + (h >= 12 ? \"PM\" : \"AM\"); }\n  function buttons(list, label) {\n    var box = $(\"slots\"); box.innerHTML = \"\"; $(\"window\").value = \"\";\n    list.forEach(function (v) {\n      var b = document.createElement(\"button\"); b.type = \"button\"; b.className = \"slot-button\"; b.textContent = label ? label(v) : v;\n      b.addEventListener(\"click\", function () {\n        box.querySelectorAll(\".slot-button\").forEach(function (x) { x.classList.remove(\"is-selected\"); x.setAttribute(\"aria-pressed\", \"false\"); });\n        b.classList.add(\"is-selected\"); b.setAttribute(\"aria-pressed\", \"true\"); $(\"window\").value = b.textContent; $(\"err\").hidden = true;\n      });\n      b.setAttribute(\"aria-pressed\", \"false\");\n      box.appendChild(b);\n    });\n  }\n  $(\"date\").addEventListener(\"change\", function () {\n    var d = this.value; if (!d) return;\n    $(\"slots\").innerHTML = '<p class=\"slot-hint\">Checking availability&hellip;</p>';\n    fetch(\"/.netlify/functions/availability?date=\" + encodeURIComponent(d))\n      .then(function (r) { if (!r.ok) throw new Error(); return r.json(); })\n      .then(function (data) {\n        if (data && data.slots && data.slots.length) buttons(data.slots, fmt);\n        else { buttons(WINDOWS); $(\"slots\").insertAdjacentHTML(\"afterbegin\", '<p class=\"slot-empty\" style=\"width:100%\">No open set times that day. Pick a time of day and Hadi will work it out.</p>'); }\n      })\n      .catch(function () { buttons(WINDOWS); });\n  });\n\n  form.addEventListener(\"submit\", function (e) {\n    e.preventDefault();\n    var fd = new FormData(form), body = {};\n    fd.forEach(function (v, k) { body[k] = String(v); });\n    body.website = body[\"bot-field\"] || \"\";\n    var err = $(\"err\"); err.hidden = true;\n    var miss = [];\n    if (!body.package) miss.push(\"a package\");\n    if (!body.date) miss.push(\"a date\");\n    if (!body.address || !body.address.trim()) miss.push(\"the property address\");\n    if (!body.name || !body.name.trim()) miss.push(\"your name\");\n    if ((body.phone || \"\").replace(/\\D/g, \"\").length < 10) miss.push(\"a mobile number\");\n    if (miss.length) { err.textContent = \"Please add \" + miss.join(\", \") + \".\"; err.hidden = false; return; }\n    $(\"go\").disabled = true; $(\"go\").textContent = \"Sending\u2026\";\n    fetch(API + \"/api/book\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify(body) })\n      .then(function (r) { return r.json().then(function (j) { if (!r.ok) throw new Error(j.error || \"Error\"); return j; }); })\n      .then(function () {\n        // Backup email alert through Netlify Forms (free) when served from altusaerials.com.\n        if (/altusaerials\\.com$/.test(location.hostname)) {\n          fetch(\"/\", { method: \"POST\", headers: { \"content-type\": \"application/x-www-form-urlencoded\" }, body: new URLSearchParams(fd).toString() }).catch(function () {});\n        }\n        form.hidden = true; $(\"done\").hidden = false; $(\"done\").scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n      })\n      .catch(function (x) {\n        err.textContent = (x && x.message && x.message !== \"Error\" ? x.message : \"That didn't go through. Check your connection, or text Hadi at (708) 778-0566.\");\n        err.hidden = false; $(\"go\").disabled = false; $(\"go\").textContent = \"Request Shoot\";\n      });\n  });\n})();\n</script>\n</body>\n</html>\n"}};

const PACKAGES = ["Overview", "Showcase", "Signature", "Summit"];
const EVENTS = new Set(["open", "view_photo", "download_all", "download_photo", "share", "open_tour", "copy_tour", "book_click"]);
const enc = new TextEncoder();

export default {
  async fetch(req, env, ctx) {
    const url = new URL(req.url);
    const path = url.pathname;
    try {
      if (req.method === "OPTIONS") return cors(new Response(null, { status: 204 }));

      // Front-end files bundled into the Worker (gallery assets, studio + rebook pages for pre-deploy testing)
      if (req.method === "GET" && ASSETS[path]) return asset(path, url);
      if (req.method === "GET" && ASSETS[path + "index.html"]) return asset(path + "index.html", url);
      if (req.method === "GET" && ASSETS[path + "/index.html"]) return Response.redirect(url.origin + path + "/", 301);

      let m;
      if ((m = path.match(/^\/gallery\/([a-z0-9-]{1,80})\/?$/)) && req.method === "GET") return galleryPage(m[1], url, env);
      if ((m = path.match(/^\/api\/g\/([a-z0-9-]{1,80})$/)) && req.method === "POST") return cors(await unlockGallery(m[1], req, url, env));
      if (path.startsWith("/m/") && (req.method === "GET" || req.method === "HEAD")) return media(path.slice(3), req, url, env);
      if (path === "/api/ping" && req.method === "POST") return cors(await ping(req, env));
      if (path === "/api/rebook/prefill" && req.method === "GET") return cors(await prefill(url, env));
      if (path === "/api/book" && req.method === "POST") return cors(await book(req, env, ctx));

      if (path.startsWith("/api/studio/")) {
        if (!(await authorized(req, env))) return cors(json({ error: "Wrong studio passphrase." }, 401));
        const r = path.slice("/api/studio/".length);
        if (r === "whoami" && req.method === "GET") return cors(json({ ok: true, flightpath: Flightpath.enabled(env), autoSend: env.AUTO_SEND === "true" }));
        if (r === "shoots" && req.method === "GET") return cors(json(await Flightpath.listUndelivered(env).catch(e => ({ connected: false, error: String(e.message || e), shoots: [] }))));
        if (r === "file" && req.method === "PUT") return cors(await putFile(req, url, env));
        if (r === "publish" && req.method === "POST") return cors(await publish(req, url, env));
        if (r === "activity" && req.method === "GET") return cors(json(await activity(env)));
        if (r === "send-text" && req.method === "POST") return cors(json(await sendDeliveryText(env, await req.json())));
      }
      if (path === "/" ) return Response.redirect((env.PUBLIC_ORIGIN || "https://altusaerials.com") + "/", 302);
      return notFound();
    } catch (err) {
      console.error(err && err.stack || err);
      return cors(json({ error: "Something went wrong on our side. Try again in a minute." }, 500));
    }
  }
};

/* ---------------- helpers ---------------- */
function json(obj, status = 200, headers = {}) {
  return new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...headers } });
}
function cors(res) {
  const h = new Headers(res.headers);
  h.set("access-control-allow-origin", "*");
  h.set("access-control-allow-methods", "GET, HEAD, POST, PUT, OPTIONS");
  h.set("access-control-allow-headers", "authorization, content-type, x-file-name");
  h.set("access-control-expose-headers", "content-disposition, content-length");
  return new Response(res.body, { status: res.status, headers: h });
}
function esc(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
function clip(s, n) { return String(s == null ? "" : s).trim().slice(0, n); }
function b64ToBytes(b64) { const bin = atob(b64); const out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out; }
function hex(buf) { return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, "0")).join(""); }
async function sha256hex(s) { return hex(await crypto.subtle.digest("SHA-256", enc.encode(s))); }
function timingSafeEq(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0;
}
async function authorized(req, env) {
  const h = req.headers.get("authorization") || "";
  const key = h.startsWith("Bearer ") ? h.slice(7) : "";
  if (!env.STUDIO_KEY || !key) return false;
  return timingSafeEq(await sha256hex(key), await sha256hex(env.STUDIO_KEY));
}
async function hashPassword(pw, salt) {
  const k = await crypto.subtle.importKey("raw", enc.encode(pw.trim().toLowerCase()), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: enc.encode(salt), iterations: 10000 }, k, 256);
  return hex(bits);
}
function asset(path, url) {
  const a = ASSETS[path];
  let body = a.b64 ? b64ToBytes(a.body) : a.body;
  if (!a.b64 && path.endsWith("config.js")) body = `window.ALTUS_API = ${JSON.stringify(url.origin)};`;
  return new Response(body, { headers: { "content-type": a.type, "cache-control": a.type.startsWith("text/html") ? "no-cache" : "public, max-age=3600", "access-control-allow-origin": "*" } });
}
function notFound() {
  return new Response(`<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gallery not found | Altus Aerials</title>
<body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#071a33;color:#fff;font:16px/1.5 -apple-system,Segoe UI,sans-serif;text-align:center;padding:24px">
<div><h1 style="font:600 28px Georgia,serif;margin:0 0 8px">We couldn't find that gallery</h1><p style="opacity:.8;margin:0 0 18px">Double-check the link in your text, or reach Hadi at (708) 778-0566.</p>
<a href="https://altusaerials.com/" style="color:#8ec5ff">altusaerials.com</a></div></body>`, { status: 404, headers: { "content-type": "text/html; charset=utf-8" } });
}
function publicOrigin(env, url) { return (env.PUBLIC_ORIGIN || url.origin).replace(/\/$/, ""); }

/* ---------------- galleries ---------------- */
async function getGallery(env, slug) {
  return env.DB.prepare("SELECT * FROM galleries WHERE slug = ?").bind(slug).first();
}
function clientData(row, url, env) {
  const d = JSON.parse(row.data);
  const api = url.origin;
  const media = `${api}/m/${row.prefix}/`;
  return {
    slug: row.slug, address: row.address, cityLine: row.city_line || "", package: row.package, shootDate: row.shoot_date,
    imageBase: media, zipUrl: d.zipFile ? `${media}${encodeURIComponent(d.zipFile)}?dl=1` : null,
    cover: d.cover, photos: d.photos, floorPlans: d.floorPlans || [], tour: d.tour || { url: null },
    bookUrl: `${publicOrigin(env, url)}/rebook/?g=${row.slug}`,
    shareUrl: `${publicOrigin(env, url)}/gallery/${row.slug}/`,
    pingUrl: `${api}/api/ping`, logo: `${api}/assets/images/logo-white.png`
  };
}
async function galleryPage(slug, url, env) {
  const row = await getGallery(env, slug);
  if (!row) return notFound();
  const api = url.origin;
  const locked = !!row.pass_hash;
  const d = JSON.parse(row.data);
  const place = row.city_line ? `${row.address}, ${row.city_line}` : row.address;
  const pageUrl = `${publicOrigin(env, url)}/gallery/${slug}/`;
  const ogImage = locked ? `${api}/assets/gallery/og-default.jpg` : `${api}/m/${row.prefix}/full/${d.cover}.jpg`;
  const desc = locked ? "Private listing gallery by Altus Aerials." :
    `${d.photos.length} listing photos${/signature|summit/i.test(row.package) ? ", floor plans and a 3D tour" : ""}. Photos by Altus Aerials.`;
  const og = [
    `<title>${esc(place)} | Altus Aerials</title>`,
    `<meta name="description" content="${esc(desc)}">`,
    `<meta property="og:type" content="website">`,
    `<meta property="og:site_name" content="Altus Aerials">`,
    `<meta property="og:title" content="${esc(place)}">`,
    `<meta property="og:description" content="${esc(desc)}">`,
    `<meta property="og:image" content="${esc(ogImage)}">`,
    `<meta property="og:image:secure_url" content="${esc(ogImage)}">`,
    `<meta property="og:image:type" content="image/jpeg">`,
    `<meta property="og:image:alt" content="${esc(locked ? "Altus Aerials" : "Front of " + place)}">`,
    `<meta property="og:url" content="${esc(pageUrl)}">`,
    `<meta name="twitter:card" content="summary_large_image">`,
    `<link rel="canonical" href="${esc(pageUrl)}">`
  ].join("\n");
  const data = locked
    ? { locked: true, slug, address: row.address, cityLine: row.city_line || "", api }
    : clientData(row, url, env);
  const html = ASSETS["/assets/gallery/template.html"].body
    .replace("<!--OG-->", og)
    .replace(/__API__/g, api)
    .replace("<!--DATA-->", `<script id="gallery-data" type="application/json">${JSON.stringify(data).replace(/</g, "\\u003c")}</script>`);
  return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-robots-tag": "noindex" } });
}
async function unlockGallery(slug, req, url, env) {
  const row = await getGallery(env, slug);
  if (!row) return json({ error: "Not found" }, 404);
  if (row.pass_hash) {
    let pw = "";
    try { pw = String((await req.json()).password || ""); } catch (e) {}
    await new Promise(r => setTimeout(r, 300)); // slow down guessing a little
    if (!pw || !timingSafeEq(await hashPassword(pw, row.pass_salt), row.pass_hash)) return json({ error: "Wrong password" }, 403);
  }
  return json(clientData(row, url, env));
}

/* ---------------- media from R2 ---------------- */
async function media(key, req, url, env) {
  key = decodeURIComponent(key);
  if (!/^g\/[a-z0-9-]+\/[A-Za-z0-9 ._()\/-]+$/.test(key) || key.includes("..")) return new Response("Not found", { status: 404 });
  const obj = await env.MEDIA.get(key, { range: req.headers, onlyIf: req.headers });
  if (!obj) return new Response("Not found", { status: 404 });
  const h = new Headers();
  obj.writeHttpMetadata(h);
  h.set("etag", obj.httpEtag);
  h.set("accept-ranges", "bytes");
  h.set("access-control-allow-origin", "*");
  h.set("access-control-expose-headers", "content-disposition, content-length");
  h.set("cache-control", "public, max-age=31536000, immutable");
  if (url.searchParams.has("dl")) {
    const name = (obj.customMetadata && obj.customMetadata.filename) || key.split("/").pop();
    h.set("content-disposition", `attachment; filename="${name.replace(/["\\]/g, "")}"; filename*=UTF-8''${encodeURIComponent(name)}`);
  }
  if (!("body" in obj) || !obj.body) return new Response(null, { status: 304, headers: h });
  let status = 200;
  if (obj.range && req.headers.has("range")) {
    const r = obj.range, start = r.offset || 0, len = r.length != null ? r.length : obj.size - start;
    h.set("content-range", `bytes ${start}-${start + len - 1}/${obj.size}`);
    h.set("content-length", String(len));
    status = 206;
  } else h.set("content-length", String(obj.size));
  return new Response(req.method === "HEAD" ? null : obj.body, { status, headers: h });
}

/* ---------------- tracking ---------------- */
async function ping(req, env) {
  let b; try { b = JSON.parse(await req.text()); } catch (e) { return json({ ok: false }, 400); }
  const slug = clip(b.g, 80), ev = clip(b.e, 20);
  if (!/^[a-z0-9-]+$/.test(slug) || !EVENTS.has(ev)) return json({ ok: false }, 400);
  await env.DB.prepare("INSERT INTO events (slug, event, photo, visitor, ts) SELECT ?, ?, ?, ?, ? WHERE EXISTS (SELECT 1 FROM galleries WHERE slug = ?)")
    .bind(slug, ev, clip(b.p, 60) || null, clip(b.v, 16) || null, Date.now(), slug).run();
  return json({ ok: true });
}

/* ---------------- booking requests (no login) ---------------- */
async function prefill(url, env) {
  const slug = clip(url.searchParams.get("g"), 80);
  const row = slug && await env.DB.prepare("SELECT agent_name, agent_phone, agent_email, package FROM galleries WHERE slug = ?").bind(slug).first();
  if (!row) return json({});
  return json({ name: row.agent_name || "", phone: row.agent_phone || "", email: row.agent_email || "", lastPackage: row.package || "" });
}
async function book(req, env, ctx) {
  let b; try { b = await req.json(); } catch (e) { return json({ error: "Please fill in the form and try again." }, 400); }
  if (b.website) return json({ ok: true }); // honeypot
  const r = {
    name: clip(b.name, 80), phone: clip(b.phone, 30), email: clip(b.email, 120), address: clip(b.address, 160),
    city: clip(b.city, 80), package: clip(b.package, 20), date: clip(b.date, 10), window: clip(b.window, 20),
    notes: clip(b.notes, 1000), from: clip(b.from, 80)
  };
  const missing = [];
  if (!r.name) missing.push("your name");
  if (r.phone.replace(/\D/g, "").length < 10) missing.push("a phone number");
  if (!r.address) missing.push("the property address");
  if (!PACKAGES.includes(r.package)) missing.push("a package");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(r.date)) missing.push("a date");
  if (missing.length) return json({ error: "Please add " + missing.join(", ") + "." }, 400);
  const res = await env.DB.prepare(`INSERT INTO bookings (created_at, name, phone, email, address, city, package, date, time_window, notes, from_slug, status)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'requested')`)
    .bind(Date.now(), r.name, r.phone, r.email, r.address, r.city, r.package, r.date, r.window, r.notes, r.from || null).run();
  const id = res.meta && res.meta.last_row_id;
  ctx.waitUntil(Flightpath.createRequest(env, r).then(fpId => fpId && env.DB.prepare("UPDATE bookings SET flightpath_id = ? WHERE id = ?").bind(fpId, id).run()).catch(e => console.error("flightpath", e)));
  return json({ ok: true, id });
}

/* ---------------- studio ---------------- */
async function putFile(req, url, env) {
  const key = url.searchParams.get("key") || "";
  if (!/^g\/[a-z0-9-]+-[a-z0-9]{10,}\/(full|thumb|plans|zip)\/[A-Za-z0-9 ._()-]{1,120}$/.test(key)) return json({ error: "Bad file path" }, 400);
  const type = req.headers.get("content-type") || "application/octet-stream";
  if (!/^(image\/(jpeg|png)|application\/zip)$/.test(type)) return json({ error: "Only JPG, PNG and ZIP files" }, 415);
  const filename = clip(req.headers.get("x-file-name"), 140) || key.split("/").pop();
  await env.MEDIA.put(key, req.body, { httpMetadata: { contentType: type }, customMetadata: { filename } });
  return json({ ok: true, key });
}
function slugify(s) { return String(s).toLowerCase().replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "gallery"; }
async function publish(req, url, env) {
  const b = await req.json();
  const address = clip(b.address, 160);
  if (!address) return json({ error: "Add the property address." }, 400);
  if (!PACKAGES.includes(b.package)) return json({ error: "Pick a package." }, 400);
  if (!/^g\/[a-z0-9-]+-[a-z0-9]{10,}$/.test(b.prefix || "")) return json({ error: "Upload didn't finish. Publish again." }, 400);
  const photos = (b.photos || []).filter(p => p && /^(ext|int)-\d{2,3}$/.test(p.id) && (p.kind === "EXT" || p.kind === "INT"))
    .map(p => ({ id: p.id, kind: p.kind, n: p.n | 0, tw: p.tw | 0, th: p.th | 0 }));
  if (!photos.length) return json({ error: "No photos to publish." }, 400);
  const data = {
    cover: photos.some(p => p.id === b.cover) ? b.cover : photos[0].id,
    photos,
    floorPlans: (b.floorPlans || []).slice(0, 8).map(f => ({ label: clip(f.label, 40) || "Floor plan", src: clip(f.src, 140), file: clip(f.file, 120) })),
    tour: { url: /^https:\/\//.test(b.tourUrl || "") ? clip(b.tourUrl, 500) : null, embed: false },
    zipFile: clip(b.zipFile, 140) || null
  };
  // unique slug: 3524-saratoga-ave, then 3524-saratoga-ave-2 …
  let slug;
  if (b.replaceSlug && /^[a-z0-9-]{1,80}$/.test(b.replaceSlug) && await getGallery(env, b.replaceSlug)) slug = b.replaceSlug; // re-publish same link
  else {
    const base = slugify(b.slug || address); slug = base;
    for (let n = 2; await getGallery(env, slug); n++) slug = `${base}-${n}`;
  }
  let salt = null, hash = null;
  if (b.password && String(b.password).trim()) { salt = crypto.randomUUID(); hash = await hashPassword(String(b.password), salt); }
  await env.DB.prepare(`INSERT OR REPLACE INTO galleries (slug, address, city_line, package, shoot_date, agent_name, agent_phone, agent_email, flightpath_id, prefix, data, pass_salt, pass_hash, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
    .bind(slug, address, clip(b.cityLine, 80), b.package, clip(b.shootDate, 10), clip(b.agentName, 80), clip(b.agentPhone, 30), clip(b.agentEmail, 120),
      clip(b.flightpathId, 80) || null, b.prefix, JSON.stringify(data), salt, hash, Date.now()).run();
  const galleryUrl = `${publicOrigin(env, url)}/gallery/${slug}/`;
  let flightpath = { ok: false, reason: "not-connected" };
  if (b.flightpathId) flightpath = await Flightpath.markDelivered(env, b.flightpathId, galleryUrl).catch(e => ({ ok: false, reason: String(e.message || e) }));
  return json({ ok: true, slug, url: galleryUrl, flightpath, autoSend: env.AUTO_SEND === "true" });
}
async function activity(env) {
  const galleries = (await env.DB.prepare(`SELECT g.slug, g.address, g.city_line, g.package, g.shoot_date, g.agent_name, g.agent_phone, g.created_at,
      (g.pass_hash IS NOT NULL) AS locked,
      SUM(e.event = 'open') AS opens, COUNT(DISTINCT CASE WHEN e.event = 'open' THEN e.visitor END) AS visitors,
      MIN(CASE WHEN e.event = 'open' THEN e.ts END) AS first_open, MAX(e.ts) AS last_seen,
      SUM(e.event = 'download_all') AS zips, SUM(e.event = 'download_photo') AS saves,
      SUM(e.event IN ('open_tour', 'copy_tour')) AS tour, SUM(e.event = 'share') AS shares, SUM(e.event = 'book_click') AS book_clicks
    FROM galleries g LEFT JOIN events e ON e.slug = g.slug GROUP BY g.slug ORDER BY g.created_at DESC LIMIT 200`).all()).results;
  const bookings = (await env.DB.prepare("SELECT * FROM bookings ORDER BY created_at DESC LIMIT 100").all()).results;
  // Agents: last shoot = latest delivered gallery or Flightpath shoot, matched on phone digits.
  const agents = {};
  const key = p => String(p || "").replace(/\D/g, "").slice(-10);
  for (const g of galleries) {
    const k = key(g.agent_phone); if (!k) continue;
    const a = agents[k] || (agents[k] = { name: g.agent_name, phone: g.agent_phone, last: "", shoots: 0 });
    a.shoots++; if ((g.shoot_date || "") > a.last) a.last = g.shoot_date;
  }
  // Booking requests aren't confirmed shoots, so they don't count toward "last shoot".
  const fp = await Flightpath.lastBookingsByPhone(env).catch(() => null);
  if (fp) for (const [k, v] of Object.entries(fp)) { const a = agents[k] || (agents[k] = { name: v.name, phone: v.phone, last: "", shoots: 0 }); if (v.last > a.last) a.last = v.last; }
  return { galleries, bookings, agents: Object.values(agents), source: fp ? "flightpath" : "galleries" };
}

/* ---------------- delivery text (manual today, auto later) ---------------- */
async function sendDeliveryText(env, { to, body }) {
  if (env.AUTO_SEND !== "true" || !env.TWILIO_SID) return { sent: false, reason: "auto-send is off" };
  const digits = String(to || "").replace(/\D/g, "");
  if (digits.length < 10) return { sent: false, reason: "no phone number" };
  const r = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${env.TWILIO_SID}/Messages.json`, {
    method: "POST",
    headers: { authorization: "Basic " + btoa(`${env.TWILIO_SID}:${env.TWILIO_TOKEN}`), "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ To: "+1" + digits.slice(-10), From: env.TWILIO_FROM, Body: clip(body, 1200) })
  });
  return { sent: r.ok, status: r.status };
}

/* ---------------- Flightpath (Firebase project flightpath-altus) ----------------
 * Talks to Flightpath's Firestore "shoots" collection with a service account
 * signing in as its own Flightpath user (FP_EMAIL / FP_PASSWORD / FIREBASE_API_KEY), so Flightpath's
 * existing security rules apply. A service account (FIREBASE_SA) also works. Field names match the app:
 *   client, phone, email, address, lat, lng, date (YYYY-MM-DD), time (HH:MM), notes,
 *   paymentType ('free'|'paid'), amount, paymentStatus, paidAt,
 *   status ('scheduled'|'shot'|'editing'|'delivered'), timestamps{...}, deliveredBy, createdAt
 * Added by this integration (optional, ignored by older app versions):
 *   package, galleryUrl, source, requestedTime, fromGallery
 * Booking requests are shoots with status "requested"; Flightpath shows them in a
 * Requests section with Confirm / Decline (see the flightpath branch).
 * Everything is a no-op until those settings are added.
 */
const PRICES = { Overview: 149, Showcase: 349, Signature: 499, Summit: 649 };
const fsVal = v => {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === "boolean") return { booleanValue: v };
  if (typeof v === "number") return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (v instanceof Date) return { timestampValue: v.toISOString() };
  if (typeof v === "object") return { mapValue: { fields: Object.fromEntries(Object.entries(v).map(([k, x]) => [k, fsVal(x)])) } };
  return { stringValue: String(v) };
};
const fromFs = v => {
  if (!v) return null;
  if ("stringValue" in v) return v.stringValue;
  if ("integerValue" in v) return Number(v.integerValue);
  if ("doubleValue" in v) return v.doubleValue;
  if ("booleanValue" in v) return v.booleanValue;
  if ("timestampValue" in v) return v.timestampValue;
  if ("nullValue" in v) return null;
  if ("mapValue" in v) return Object.fromEntries(Object.entries(v.mapValue.fields || {}).map(([k, x]) => [k, fromFs(x)]));
  if ("arrayValue" in v) return (v.arrayValue.values || []).map(fromFs);
  return null;
};
const digits10 = p => String(p || "").replace(/\D/g, "").slice(-10);
const fpPhone = p => { const d = digits10(p); return d.length === 10 ? `${d.slice(0, 3)}-${d.slice(3, 6)}-${d.slice(6)}` : String(p || ""); };
function splitAddress(full) {
  // "3524 Saratoga Ave, Downers Grove, IL 60515, USA" -> street / city / state
  const parts = String(full || "").split(",").map(x => x.trim()).filter(Boolean);
  if (parts.length && /^(usa|united states)$/i.test(parts[parts.length - 1])) parts.pop();
  const street = parts[0] || "";
  let city = parts[1] || "", state = "";
  const st = (parts[2] || "").match(/^([A-Z]{2})\b/);
  if (st) state = st[1];
  else { const m = city.match(/^(.*?)\s+([A-Z]{2})(\s+\d{5})?$/); if (m) { city = m[1]; state = m[2]; } }
  return { street, city, state };
}
function to24h(label) {
  const m = String(label || "").match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return "";
  let h = +m[1] % 12; if (/pm/i.test(m[3])) h += 12;
  return `${String(h).padStart(2, "0")}:${m[2]}`;
}
const Flightpath = {
  _tok: null, _exp: 0,
  enabled(env) { return !!(env.FIREBASE_SA || (env.FP_EMAIL && env.FP_PASSWORD && env.FIREBASE_API_KEY)); },
  project(env) {
    if (env.FIREBASE_PROJECT_ID) return env.FIREBASE_PROJECT_ID;
    if (env.FIREBASE_SA) { try { return JSON.parse(env.FIREBASE_SA).project_id || "flightpath-altus"; } catch (e) {} }
    return "flightpath-altus";
  },
  base(env) {
    if (env.FIRESTORE_BASE) return env.FIRESTORE_BASE.replace(/\/$/, "");
    return `https://firestore.googleapis.com/v1/projects/${this.project(env)}/databases/(default)/documents`;
  },
  async token(env) {
    if (this._tok && Date.now() < this._exp - 60000) return this._tok;
    if (!env.FIREBASE_SA) return this.userToken(env);
    const sa = JSON.parse(env.FIREBASE_SA);
    const now = Math.floor(Date.now() / 1000);
    const tokenUrl = env.GOOGLE_TOKEN_URL || "https://oauth2.googleapis.com/token";
    const b64u = s => btoa(s).replace(/=+$/, "").replace(/\+/g, "-").replace(/\//g, "_");
    const unsigned = `${b64u(JSON.stringify({ alg: "RS256", typ: "JWT" }))}.${b64u(JSON.stringify({ iss: sa.client_email, scope: "https://www.googleapis.com/auth/datastore", aud: "https://oauth2.googleapis.com/token", iat: now, exp: now + 3600 }))}`;
    const pem = sa.private_key.replace(/-----[^-]+-----/g, "").replace(/\s+/g, "");
    const key = await crypto.subtle.importKey("pkcs8", b64ToBytes(pem), { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["sign"]);
    const sigBytes = new Uint8Array(await crypto.subtle.sign("RSASSA-PKCS1-v1_5", key, enc.encode(unsigned)));
    let bin = ""; for (const b of sigBytes) bin += String.fromCharCode(b);
    const r = await fetch(tokenUrl, { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion: `${unsigned}.${b64u(bin)}` }) });
    if (!r.ok) throw new Error("Flightpath sign-in failed (" + r.status + ")");
    const j = await r.json();
    this._tok = j.access_token; this._exp = Date.now() + (j.expires_in || 3600) * 1000;
    return this._tok;
  },
  // Signs in like the Flightpath app does (email + password), so Flightpath's own rules apply.
  async userToken(env) {
    const url = (env.IDENTITY_URL || "https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword") + "?key=" + encodeURIComponent(env.FIREBASE_API_KEY);
    const r = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json", referer: env.FP_REFERER || "https://flightpath-altus.netlify.app/" },
      body: JSON.stringify({ email: env.FP_EMAIL, password: env.FP_PASSWORD, returnSecureToken: true })
    });
    if (!r.ok) {
      let msg = ""; try { msg = (await r.json()).error.message; } catch (e) {}
      throw new Error("Flightpath sign-in failed" + (msg ? ": " + msg : ` (${r.status})`));
    }
    const j = await r.json();
    this._tok = j.idToken; this._exp = Date.now() + Number(j.expiresIn || 3600) * 1000;
    return this._tok;
  },
  async call(env, method, path, body) {
    const r = await fetch(this.base(env) + path, { method, headers: { authorization: "Bearer " + await this.token(env), "content-type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
    if (!r.ok) throw new Error(`Flightpath ${method} failed (${r.status})`);
    return r.json();
  },
  async allShoots(env) {
    const out = []; let pageToken = "";
    for (let i = 0; i < 20; i++) {
      const j = await this.call(env, "GET", `/shoots?pageSize=300${pageToken ? "&pageToken=" + encodeURIComponent(pageToken) : ""}`);
      for (const d of j.documents || []) out.push({ id: d.name.split("/").pop(), ...fromFs({ mapValue: { fields: d.fields || {} } }) });
      if (!j.nextPageToken) break; pageToken = j.nextPageToken;
    }
    return out;
  },
  async listUndelivered(env) {
    if (!this.enabled(env)) return { connected: false, shoots: [] };
    const today = new Date().toISOString().slice(0, 10);
    const cutoff = new Date(Date.now() - 45 * 864e5).toISOString().slice(0, 10);
    const shoots = (await this.allShoots(env))
      .filter(s => ["scheduled", "shot", "editing"].includes(s.status) && s.date && s.date <= today && s.date >= cutoff)
      .sort((a, b) => (b.date + (b.time || "")).localeCompare(a.date + (a.time || "")))
      .map(s => {
        const a = splitAddress(s.address);
        const pkg = PACKAGES.includes(s.package) ? s.package : (Object.keys(PRICES).find(k => PRICES[k] === Number(s.amount)) || "");
        return { id: s.id, address: a.street, city: a.city, state: a.state || "IL", date: s.date, package: pkg,
          agentName: s.client || "", agentPhone: s.phone || "", agentEmail: s.email || "", status: s.status };
      });
    return { connected: true, shoots };
  },
  async markDelivered(env, id, galleryUrl) {
    if (!this.enabled(env)) return { ok: false, reason: "not-connected" };
    if (!/^[A-Za-z0-9_-]{1,100}$/.test(id)) return { ok: false, reason: "bad-id" };
    const fields = ["status", "timestamps.delivered", "deliveredBy", "galleryUrl"];
    const q = fields.map(f => "updateMask.fieldPaths=" + encodeURIComponent(f)).join("&") + "&currentDocument.exists=true";
    await this.call(env, "PATCH", `/shoots/${id}?${q}`, { fields: {
      status: fsVal("delivered"), deliveredBy: fsVal("gallery@altusaerials.com"), galleryUrl: fsVal(galleryUrl),
      timestamps: fsVal({ delivered: new Date().toISOString() }) } });
    return { ok: true };
  },
  async createRequest(env, r) {
    if (!this.enabled(env)) return null;
    const time = to24h(r.window);
    const lines = [`Booking request from the gallery page: ${r.package}.`, `Preferred: ${r.date}${r.window ? ", " + r.window : ""}.`];
    if (r.notes) lines.push(r.notes);
    const doc = {
      client: r.name, phone: fpPhone(r.phone), email: r.email || "",
      address: r.city ? `${r.address}, ${r.city}` : r.address, lat: null, lng: null,
      date: r.date, time, notes: lines.join("\n"),
      paymentType: "paid", amount: PRICES[r.package] || null, paymentStatus: "pending", paidAt: null,
      status: "requested", package: r.package, source: "rebook", requestedTime: r.window || "", fromGallery: r.from || "",
      timestamps: { requested: new Date().toISOString(), scheduled: null, shot: null, editing: null, delivered: null },
      createdAt: new Date()
    };
    const j = await this.call(env, "POST", "/shoots", { fields: Object.fromEntries(Object.entries(doc).map(([k, v]) => [k, fsVal(v)])) });
    return j.name ? j.name.split("/").pop() : null;
  },
  async lastBookingsByPhone(env) {
    if (!this.enabled(env)) return null;
    const map = {};
    for (const s of await this.allShoots(env)) {
      if (s.status === "requested" || !s.date) continue;
      const k = digits10(s.phone); if (k.length !== 10) continue;
      const a = map[k] || (map[k] = { name: s.client || "", phone: s.phone, last: "" });
      if (s.date > a.last) { a.last = s.date; a.name = s.client || a.name; }
    }
    return map;
  }
};
